import { displayPrefix } from "./semantics";
import type { GraphNode } from "./types";

export interface LayoutPoint {
  x: number;
  y: number;
}

const saved = new Map<string, LayoutPoint>();

export function layoutNodes(
  nodes: GraphNode[],
  edges: { source: string; target: string }[],
  opts?: { fresh?: boolean },
): Map<string, LayoutPoint> {
  const pos = new Map<string, LayoutPoint>();
  if (!nodes.length) return pos;

  const groups = new Map<string, GraphNode[]>();
  for (const n of nodes) {
    const key = displayPrefix(n.prefix) || n.type || "other";
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key)!.push(n);
  }

  if (!opts?.fresh && nodes.every((n) => saved.has(n.id))) {
    for (const n of nodes) {
      const p = saved.get(n.id)!;
      pos.set(n.id, { x: p.x, y: p.y });
    }
    return pos;
  }

  const keys = [...groups.keys()].sort();
  const ring = opts?.fresh
    ? Math.max(140, 48 * Math.sqrt(keys.length) + 22 * Math.sqrt(nodes.length))
    : Math.max(420, 140 * Math.sqrt(keys.length));
  keys.forEach((key, gi) => {
    const members = groups.get(key)!;
    const angle = (gi / keys.length) * Math.PI * 2 - Math.PI / 2;
    const cx = Math.cos(angle) * ring;
    const cy = Math.sin(angle) * ring;
    const localR = 48 + 22 * Math.sqrt(members.length);
    members.forEach((n, i) => {
      const prev = opts?.fresh ? undefined : saved.get(n.id);
      if (prev) {
        pos.set(n.id, { x: prev.x, y: prev.y });
        return;
      }
      const a = (i / Math.max(1, members.length)) * Math.PI * 2;
      const r = members.length === 1 ? 0 : localR * (0.35 + 0.65 * ((i % 5) / 5));
      pos.set(n.id, { x: cx + Math.cos(a) * r, y: cy + Math.sin(a) * r });
    });
  });

  const ids = nodes.map((n) => n.id);
  const index = new Map(ids.map((id, i) => [id, i]));
  const adj: number[][] = ids.map(() => []);
  for (const e of edges) {
    const a = index.get(e.source);
    const b = index.get(e.target);
    if (a == null || b == null || a === b) continue;
    adj[a].push(b);
    adj[b].push(a);
  }

  const iters = opts?.fresh
    ? Math.min(80, 18 + Math.floor(4000 / Math.max(8, nodes.length)))
    : Math.min(24, 8 + Math.floor(1200 / Math.max(8, nodes.length)));
  for (let k = 0; k < iters; k++) {
    for (let i = 0; i < ids.length; i++) {
      const a = pos.get(ids[i])!;
      let fx = 0;
      let fy = 0;
      for (let j = i + 1; j < ids.length; j++) {
        const b = pos.get(ids[j])!;
        let dx = a.x - b.x;
        let dy = a.y - b.y;
        let d2 = dx * dx + dy * dy;
        if (d2 < 4) {
          dx = (Math.random() - 0.5) * 8;
          dy = (Math.random() - 0.5) * 8;
          d2 = dx * dx + dy * dy;
        }
        const d = Math.sqrt(d2);
        if (d < 140) {
          const force = (140 - d) / d * 0.35;
          fx += dx * force;
          fy += dy * force;
          b.x -= dx * force * 0.5;
          b.y -= dy * force * 0.5;
        }
      }
      for (const j of adj[i]) {
        if (j <= i) continue;
        const b = pos.get(ids[j])!;
        const dx = b.x - a.x;
        const dy = b.y - a.y;
        const d = Math.hypot(dx, dy) || 1;
        const pull = (d - 150) * 0.012;
        a.x += dx / d * pull;
        a.y += dy / d * pull;
        b.x -= dx / d * pull;
        b.y -= dy / d * pull;
      }
      a.x += fx * 0.08;
      a.y += fy * 0.08;
    }
  }

  if (!opts?.fresh) {
    for (const n of nodes) {
      const p = pos.get(n.id);
      if (p) saved.set(n.id, { x: p.x, y: p.y });
    }
  }
  return pos;
}

export function rememberPosition(id: string, x: number, y: number): void {
  saved.set(id, { x, y });
}

export function layoutNewAround(
  newNodes: GraphNode[],
  anchor: LayoutPoint,
): Map<string, LayoutPoint> {
  const pos = new Map<string, LayoutPoint>();
  if (!newNodes.length) return pos;
  const count = newNodes.length;
  const baseR = 88 + 24 * Math.sqrt(count);
  newNodes.forEach((n, i) => {
    const a = (i / count) * Math.PI * 2 - Math.PI / 2 + (i % 2 ? 0.12 : 0);
    const ring = baseR * (0.75 + 0.25 * ((i % 4) / 4));
    const p = { x: anchor.x + Math.cos(a) * ring, y: anchor.y + Math.sin(a) * ring };
    pos.set(n.id, p);
    saved.set(n.id, p);
  });
  return pos;
}

/** Шаг колец и зазоры: для больших пучков (≥100) — просторнее. */
function bundleLayoutSpacing(n: number): { minArc: number; layerStep: number; minGap: number; repulseIters: number } {
  if (n < 100) {
    const minArc = 92;
    return {
      minArc,
      layerStep: Math.max(52, Math.min(88, 620 / Math.sqrt(Math.max(n, 1)))),
      minGap: Math.max(72, minArc * 0.78),
      repulseIters: 48,
    };
  }
  const bulk = Math.sqrt(n / 100);
  const minArc = Math.min(128, 96 + bulk * 14);
  return {
    minArc,
    layerStep: Math.max(66 * bulk, Math.min(130, (560 / Math.sqrt(n)) * bulk * 1.08)),
    minGap: Math.max(84, minArc * 0.82),
    repulseIters: Math.min(72, 48 + Math.floor(n / 40)),
  };
}

export function layoutBundleAroundSeed(
  seedId: string,
  nodeIds: string[],
  links: { source: string; target: string }[],
  anchor: LayoutPoint,
): Map<string, LayoutPoint> {
  const pos = new Map<string, LayoutPoint>();
  if (!nodeIds.length) return pos;
  const visible = new Set(nodeIds);
  const adj = new Map<string, string[]>();
  for (const id of nodeIds) adj.set(id, []);
  for (const e of links) {
    if (!visible.has(e.source) || !visible.has(e.target)) continue;
    adj.get(e.source)!.push(e.target);
    adj.get(e.target)!.push(e.source);
  }

  const depth = new Map<string, number>();
  const q: string[] = visible.has(seedId) ? [seedId] : [nodeIds[0]];
  depth.set(q[0], 0);
  for (let qi = 0; qi < q.length; qi++) {
    const id = q[qi];
    for (const nb of adj.get(id) || []) {
      if (depth.has(nb)) continue;
      depth.set(nb, depth.get(id)! + 1);
      q.push(nb);
    }
  }
  let maxDepth = 0;
  for (const id of nodeIds) {
    if (!depth.has(id)) depth.set(id, 999);
    maxDepth = Math.max(maxDepth, depth.get(id)!);
  }
  for (const id of nodeIds) {
    if (depth.get(id) === 999) depth.set(id, maxDepth + 1);
  }

  const layers = new Map<number, string[]>();
  for (const id of nodeIds) {
    const d = depth.get(id)!;
    if (!layers.has(d)) layers.set(d, []);
    layers.get(d)!.push(id);
  }

  const n = nodeIds.length;
  const { minArc, layerStep, minGap, repulseIters } = bundleLayoutSpacing(n);
  pos.set(q[0], { x: anchor.x, y: anchor.y });

  for (const [d, ids] of [...layers.entries()].sort((a, b) => a[0] - b[0])) {
    if (d === 0) continue;
    const count = ids.length;
    const baseR = layerStep * d;
    const maxPerRing = Math.max(5, Math.floor((2 * Math.PI * Math.max(baseR, layerStep)) / minArc));
    let idx = 0;
    let sub = 0;
    while (idx < count) {
      const chunk = ids.slice(idx, idx + maxPerRing);
      const ringCount = chunk.length;
      const neededR = (ringCount * minArc) / (2 * Math.PI);
      const r = Math.max(baseR + sub * layerStep * (n >= 100 ? 0.82 : 0.72), neededR);
      chunk.forEach((id, i) => {
        const a = (i / ringCount) * Math.PI * 2 - Math.PI / 2 + sub * 0.08;
        pos.set(id, { x: anchor.x + Math.cos(a) * r, y: anchor.y + Math.sin(a) * r });
      });
      idx += maxPerRing;
      sub += 1;
    }
  }

  const ids = nodeIds.filter((id) => pos.has(id));
  const minD = minGap;
  for (let k = 0; k < repulseIters; k++) {
    for (let i = 0; i < ids.length; i++) {
      const idA = ids[i];
      const a = pos.get(idA)!;
      let fx = 0;
      let fy = 0;
      for (let j = i + 1; j < ids.length; j++) {
        const idB = ids[j];
        const b = pos.get(idB)!;
        const dx = a.x - b.x;
        const dy = a.y - b.y;
        const dist = Math.hypot(dx, dy) || 1;
        if (dist < minD) {
          const push = (minD - dist) / dist * 0.55;
          fx += dx * push;
          fy += dy * push;
          b.x -= dx * push * 0.5;
          b.y -= dy * push * 0.5;
        }
      }
      if (idA !== seedId) {
        const dx = anchor.x - a.x;
        const dy = anchor.y - a.y;
        const dist = Math.hypot(dx, dy) || 1;
        const target = layerStep * (depth.get(idA) || 1);
        const pull = (dist - target) * 0.05;
        a.x += dx / dist * pull;
        a.y += dy / dist * pull;
      }
      a.x += fx * 0.1;
      a.y += fy * 0.1;
    }
  }

  for (const [id, p] of pos) saved.set(id, p);
  return pos;
}

export function clearLayoutMemory(): void {
  saved.clear();
}
