import { el } from "./chrome";

export function bindFloatPanels(): void {
  const wrap = el("graphWrap");
  document.querySelectorAll<HTMLElement>(".float-panel").forEach((panel) => {
    const head = panel.querySelector<HTMLElement>(".float-head");
    if (!head) return;
    let dragging = false;
    let ox = 0;
    let oy = 0;
    let startLeft = 0;
    let startTop = 0;

    head.addEventListener("pointerdown", (ev) => {
      if (ev.button !== 0) return;
      dragging = true;
      ox = ev.clientX;
      oy = ev.clientY;
      const panelRect = panel.getBoundingClientRect();
      const wrapRect = wrap.getBoundingClientRect();
      startLeft = panelRect.left - wrapRect.left;
      startTop = panelRect.top - wrapRect.top;
      panel.style.right = "auto";
      panel.style.left = `${startLeft}px`;
      panel.style.top = `${startTop}px`;
      head.setPointerCapture(ev.pointerId);
      ev.preventDefault();
    });

    head.addEventListener("pointermove", (ev) => {
      if (!dragging) return;
      const panelW = panel.getBoundingClientRect().width;
      const panelH = panel.getBoundingClientRect().height;
      const maxLeft = Math.max(0, wrap.clientWidth - panelW);
      const maxTop = Math.max(0, wrap.clientHeight - panelH);
      const left = Math.min(maxLeft, Math.max(0, startLeft + ev.clientX - ox));
      const top = Math.min(maxTop, Math.max(0, startTop + ev.clientY - oy));
      panel.style.left = `${left}px`;
      panel.style.top = `${top}px`;
    });

    const stop = () => {
      dragging = false;
    };
    head.addEventListener("pointerup", stop);
    head.addEventListener("pointercancel", stop);
  });
}

export function bindGraphHeader(): void {
  const wrap = el("graphWrap");
  const chrome = wrap.querySelector<HTMLElement>(".graph-chrome");
  if (!chrome) return;
  const sync = () => wrap.style.setProperty("--graph-header", `${chrome.offsetHeight}px`);
  sync();
  window.addEventListener("resize", sync);
  if (typeof ResizeObserver !== "undefined") {
    new ResizeObserver(sync).observe(chrome);
  }
}
