import {
  DEFAULT_OFF,
  FLOW_ENDS,
  HIDDEN_HOPS,
  LOAD_CUTOFF,
  LOAD_EDGES,
  PROVIDERS,
  bwText,
  displayPrefix,
  isColdProvider,
  isEmptyObject,
  laterDate,
  pairName,
  yyyymmdd,
} from "./semantics";
import type {
  GraphEdge,
  GraphFrame,
  GraphNode,
  LineageGraph,
  Snapshots,
  UiFilters,
  ViaEdge,
} from "./types";

function collapseBw2hanaShadows(graph: LineageGraph): LineageGraph {
  const prefer = ["odso", "adso", "cube", "hcpr"];
  const byId = Object.fromEntries((graph.nodes || []).map((n) => [n.id, n]));
  const alias = new Map<string, string>();
  const isShadow = (s: string) => /system-local\.bw\.bw2hana/i.test(s) || /0BW:BIA:/i.test(s);
  const canon = (name: string) => String(name || "")
    .replace(/^_SYS_BIC[:.]/i, "")
    .replace(/^SAPPBI\./i, "")
    .replace(/^system-local\.bw\.bw2hana[^/]*\//i, "")
    .replace(/^0BW:BIA:/i, "")
    .replace(/\.U1$/i, "");
  for (const n of graph.nodes || []) {
    if (!isShadow(n.name) && !isShadow(n.id)) continue;
    const c = canon(n.name);
    if (!c) continue;
    let target = "";
    for (const t of prefer) {
      const id = `${t}:${c}`;
      if (byId[id] && id !== n.id) { target = id; break; }
    }
    if (!target) {
      const same = `${n.type}:${c}`;
      if (byId[same] && same !== n.id) target = same;
    }
    if (target) alias.set(n.id, target);
  }
  if (!alias.size) return graph;
  graph.nodes = graph.nodes.filter((n) => !alias.has(n.id));
  const seen = new Set<string>();
  graph.edges = (graph.edges || []).filter((e) => {
    const s = alias.get(e.source) || e.source;
    const t = alias.get(e.target) || e.target;
    if (s === t) return false;
    const nid = `${e.type}|${s}|${t}`;
    if (seen.has(nid)) return false;
    seen.add(nid);
    e.source = s;
    e.target = t;
    e.id = nid;
    return true;
  });
  return graph;
}

export class GraphModel {
  readonly graph: LineageGraph;
  readonly texts: Record<string, string>;
  readonly lastOkMap: Record<string, string>;
  readonly lastDataMap: Record<string, string>;
  readonly nodeById: Record<string, GraphNode>;
  readonly types: string[];
  readonly prefixes: string[];
  readonly stalePairs: { src: string; tgt: string; sid: string; tid: string; last: string }[];
  readonly neverDtpPairs = new Set<string>();
  readonly knownDtpPairs = new Set<string>();
  private readonly outAdj = new Map<string, GraphEdge[]>();
  private readonly inAdj = new Map<string, GraphEdge[]>();
  private readonly calcViewHasConsumer = new Map<string, boolean>();

  constructor(snapshots: Snapshots) {
    this.graph = collapseBw2hanaShadows(snapshots.graph);
    this.texts = snapshots.texts;
    this.lastOkMap = snapshots.lastOk;
    this.lastDataMap = snapshots.lastData;
    this.nodeById = Object.fromEntries(this.graph.nodes.map((n) => [n.id, n]));
    this.graph.nodes.forEach((n) => { n.txtlg = n.txtlg || bwText(n, this.texts); });
    const addAdj = (map: Map<string, GraphEdge[]>, id: string, edge: GraphEdge) => {
      if (!map.has(id)) map.set(id, []);
      map.get(id)!.push(edge);
    };
    this.graph.edges.forEach((edge) => {
      addAdj(this.outAdj, edge.source, edge);
      addAdj(this.inAdj, edge.target, edge);
    });
    this.types = [...new Set(this.graph.nodes.map((n) => n.type))].sort();
    this.prefixes = [...new Set(this.graph.nodes.map((n) => n.prefix).filter(Boolean) as string[])].sort();
    for (const n of this.graph.nodes) {
      if (n.type !== "dtp") continue;
      const ends = this.parseDtpEnds(n);
      if (!ends) continue;
      const key = `${ends.src}|${ends.tgt}`;
      this.knownDtpPairs.add(key);
      if (!this.lastLiveForPair(ends.src, ends.tgt)) this.neverDtpPairs.add(key);
    }
    this.stalePairs = this.allStaleDtpPairs();
  }

  defaultFilters(): UiFilters {
    return {
      query: "",
      prefix: "",
      egoDepth: 2,
      egoParents: true,
      egoChildren: true,
      showFrozenLoads: true,
      showAllCv: false,
      hideLiveDtp: false,
      hideNeverDtp: false,
      enabledTypes: new Set(this.types.filter((type) => !DEFAULT_OFF.has(type))),
    };
  }

  lastOkForPair(srcName: string, tgtName: string): string {
    return yyyymmdd(this.lastOkMap[`${pairName(srcName)}|${pairName(tgtName)}`]);
  }

  lastDataForPair(srcName: string, tgtName: string): string {
    return yyyymmdd(this.lastDataMap[`${pairName(srcName)}|${pairName(tgtName)}`]);
  }

  lastLiveForPair(srcName: string, tgtName: string): string {
    return laterDate(this.lastOkForPair(srcName, tgtName), this.lastDataForPair(srcName, tgtName));
  }

  parseDtpEnds(node: GraphNode | undefined): { src: string; tgt: string } | null {
    const m = String((node && node.name) || "").match(/^(.+)>(.+):([A-Z])$/);
    if (!m) return null;
    return { src: pairName(m[1]), tgt: pairName(m[2]) };
  }

  pairKeyFromIds(sourceId: string, targetId: string): string {
    const src = this.nodeById[sourceId];
    const tgt = this.nodeById[targetId];
    if (!src || !tgt) return "";
    return `${pairName(src.name)}|${pairName(tgt.name)}`;
  }

  lastLiveOnDtpPath(path: string[] | undefined, sourceId: string, targetId: string): string {
    const src = this.nodeById[sourceId];
    const tgt = this.nodeById[targetId];
    let last = this.lastLiveForPair(src && src.name, tgt && tgt.name);
    for (const id of path || []) {
      const hop = this.nodeById[id];
      if (!hop || hop.type !== "dtp") continue;
      const ends = this.parseDtpEnds(hop);
      const d = ends
        ? this.lastLiveForPair(ends.src, ends.tgt)
        : laterDate(yyyymmdd(hop.last_ok), yyyymmdd(hop.last_data));
      if (d && (!last || d > last)) last = d;
    }
    return last;
  }

  pathHasDtp(path: string[] | undefined): boolean {
    return (path || []).some((id) => this.nodeById[id] && this.nodeById[id].type === "dtp");
  }

  dtpNodeLastOk(node: GraphNode | undefined): string {
    if (!node || node.type !== "dtp") return "";
    const ends = this.parseDtpEnds(node);
    return ends
      ? this.lastLiveForPair(ends.src, ends.tgt)
      : laterDate(yyyymmdd(node.last_ok), yyyymmdd(node.last_data));
  }

  isNeverDtp(node: GraphNode | undefined): boolean {
    return !!(node && node.type === "dtp" && !this.dtpNodeLastOk(node));
  }

  isNeverLoadEdge(edge: GraphEdge): boolean {
    if (!LOAD_EDGES.has(edge.type)) return false;
    const src = this.nodeById[edge.source];
    const tgt = this.nodeById[edge.target];
    return this.isNeverDtp(src) || this.isNeverDtp(tgt);
  }

  isNeverDtpPath(path: string[] | undefined, sourceId: string, targetId: string): boolean {
    const key = this.pairKeyFromIds(sourceId, targetId);
    if (key && this.neverDtpPairs.has(key)) return true;
    if (!this.pathHasDtp(path)) return false;
    return !this.lastLiveOnDtpPath(path, sourceId, targetId);
  }

  isStaleDtpPath(path: string[] | undefined, sourceId: string, targetId: string): boolean {
    if (this.isNeverDtpPath(path, sourceId, targetId)) return false;
    const last = this.lastLiveOnDtpPath(path, sourceId, targetId);
    if (last && last < LOAD_CUTOFF) return true;
    const key = this.pairKeyFromIds(sourceId, targetId);
    if (key && this.knownDtpPairs.has(key) && last && last < LOAD_CUTOFF) return true;
    return false;
  }

  isStaleLoadEdge(edge: GraphEdge): boolean {
    if (!LOAD_EDGES.has(edge.type)) return false;
    const src = this.nodeById[edge.source];
    const tgt = this.nodeById[edge.target];
    const dtp = src && src.type === "dtp" ? src : tgt && tgt.type === "dtp" ? tgt : null;
    if (!dtp) return false;
    const last = this.dtpNodeLastOk(dtp);
    return !!last && last < LOAD_CUTOFF;
  }

  skipNeverHop(edge: GraphEdge, hideNeverDtp: boolean): boolean {
    if (!hideNeverDtp) return false;
    return this.isNeverLoadEdge(edge)
      || this.isNeverDtp(this.nodeById[edge.source])
      || this.isNeverDtp(this.nodeById[edge.target]);
  }

  loadsIntoFrozenData(source: GraphNode | undefined, target: GraphNode | undefined, type: string): boolean {
    if (!LOAD_EDGES.has(type) || isColdProvider(target)) return !!isColdProvider(target);
    const stale = yyyymmdd(source && source.props && source.props.last_load);
    return (source?.type === "dtp" || source?.type === "trfn") &&
      !!stale && stale < LOAD_CUTOFF && !!target && PROVIDERS.has(target.type);
  }

  neighborLabel(node: GraphNode | undefined): string {
    if (!node) return "";
    const txt = bwText(node, this.texts);
    return txt ? `${node.name} — ${txt}` : node.name;
  }

  providerIdByName(name: string): string {
    const n = pairName(name);
    for (const t of ["adso", "odso", "cube", "hcpr", "datasource"]) {
      const id = `${t}:${n}`;
      if (this.nodeById[id]) return id;
    }
    return "";
  }

  private allStaleDtpPairs() {
    const seen = new Set<string>();
    const rows: { src: string; tgt: string; sid: string; tid: string; last: string }[] = [];
    for (const n of this.graph.nodes) {
      if (n.type !== "dtp") continue;
      const ends = this.parseDtpEnds(n);
      if (!ends) continue;
      const last = this.lastLiveForPair(ends.src, ends.tgt);
      if (!last || last >= LOAD_CUTOFF) continue;
      const key = `${ends.src}|${ends.tgt}`;
      if (seen.has(key)) continue;
      seen.add(key);
      const sid = this.providerIdByName(ends.src);
      const tid = this.providerIdByName(ends.tgt);
      if (!sid || !tid) continue;
      rows.push({ src: ends.src, tgt: ends.tgt, sid, tid, last: last || "" });
    }
    rows.sort((a, b) => String(a.last).localeCompare(String(b.last)) || a.src.localeCompare(b.src));
    return rows;
  }

  private prefixOk(n: GraphNode, prefix: string): boolean {
    return !prefix || n.prefix === prefix || displayPrefix(n.prefix) === prefix;
  }

  private wanted(n: GraphNode, filters: UiFilters): boolean {
    return filters.enabledTypes.has(n.type) && this.prefixOk(n, filters.prefix);
  }

  private cvHasConsumer(id: string, trail = new Set<string>()): boolean {
    if (this.calcViewHasConsumer.has(id)) return this.calcViewHasConsumer.get(id)!;
    if (trail.has(id)) return false;
    trail.add(id);
    for (const edge of this.outAdj.get(id) || []) {
      const target = this.nodeById[edge.target];
      if (!target) continue;
      if (target.type === "calcview" && this.cvHasConsumer(target.id, trail)) {
        this.calcViewHasConsumer.set(id, true);
        return true;
      }
      if (target.type !== "table" && target.type !== "infoobject" && target.type !== "calcview") {
        this.calcViewHasConsumer.set(id, true);
        return true;
      }
    }
    this.calcViewHasConsumer.set(id, false);
    return false;
  }

  private matchSeeds(query: string, allowed: Set<string>): string[] {
    const exact: string[] = [];
    const loose: string[] = [];
    const q = query.toLowerCase();
    this.graph.nodes.forEach((n) => {
      if (!allowed.has(n.id)) return;
      const name = String(n.name || "").toLowerCase();
      const label = String(n.label || "").toLowerCase();
      if (name === q || label === q || n.id.toLowerCase() === q) exact.push(n.id);
      else if (name.includes(q) || label.includes(q) || n.id.toLowerCase().includes(q)) loose.push(n.id);
    });
    return exact.length ? exact : loose;
  }

  private traverse(
    seeds: string[],
    maxDepth: number,
    parents: boolean,
    children: boolean,
    allowed: Set<string>,
    showFrozenLoads: boolean,
    hideNeverDtp: boolean,
  ): Set<string> {
    const keep = new Set(seeds);
    const walk = (seed: string, direction: "in" | "out") => {
      const seen = new Set([seed]);
      const queue = [{ id: seed, depth: 0 }];
      while (queue.length) {
        const cur = queue.shift()!;
        const edges = direction === "in" ? (this.inAdj.get(cur.id) || []) : (this.outAdj.get(cur.id) || []);
        for (const edge of edges) {
          if (!showFrozenLoads && this.loadsIntoFrozenData(this.nodeById[edge.source], this.nodeById[edge.target], edge.type)) continue;
          if (this.skipNeverHop(edge, hideNeverDtp)) continue;
          const next = direction === "in" ? edge.source : edge.target;
          if (seen.has(next)) continue;
          seen.add(next);
          const nextNode = this.nodeById[next];
          if (!nextNode) continue;
          const isVisibleEnd = FLOW_ENDS.has(nextNode.type) && allowed.has(next);
          if (isVisibleEnd) {
            if (cur.depth < maxDepth) {
              keep.add(next);
              queue.push({ id: next, depth: cur.depth + 1 });
            }
          } else if (HIDDEN_HOPS.has(nextNode.type) || FLOW_ENDS.has(nextNode.type)) {
            queue.push({ id: next, depth: cur.depth });
          }
        }
      }
    };
    seeds.forEach((seed) => {
      if (parents) walk(seed, "in");
      if (children) walk(seed, "out");
    });
    return keep;
  }

  private collapsedVias(visible: Set<string>, showFrozenLoads: boolean, hideNeverDtp: boolean): ViaEdge[] {
    const found: ViaEdge[] = [];
    const seen = new Set<string>();
    const walk = (start: string, direction: "in" | "out") => {
      const queue = [{ id: start, hops: 0, path: [start] }];
      const visited = new Set([start]);
      while (queue.length) {
        const cur = queue.shift()!;
        if (cur.hops >= 8) continue;
        const edges = direction === "in" ? (this.inAdj.get(cur.id) || []) : (this.outAdj.get(cur.id) || []);
        for (const edge of edges) {
          if (!showFrozenLoads && this.loadsIntoFrozenData(this.nodeById[edge.source], this.nodeById[edge.target], edge.type)) continue;
          if (this.skipNeverHop(edge, hideNeverDtp)) continue;
          const next = direction === "in" ? edge.source : edge.target;
          if (visited.has(next)) continue;
          const nextNode = this.nodeById[next];
          if (!nextNode || /\/proc|tabletype|VAR_OUT/i.test(nextNode.name || "")) continue;
          if (visible.has(next) && next !== start && FLOW_ENDS.has(nextNode.type) && cur.hops > 0) {
            const source = direction === "in" ? next : start;
            const target = direction === "in" ? start : next;
            const key = `${source}|${target}`;
            const path = direction === "in" ? [next, ...cur.path] : [...cur.path, next];
            if (this.isNeverDtpPath(path, source, target) && hideNeverDtp) continue;
            if (!seen.has(key)) {
              seen.add(key);
              found.push({ source, target, path });
            }
            continue;
          }
          if (!HIDDEN_HOPS.has(nextNode.type)) continue;
          if (this.isNeverDtp(nextNode) && hideNeverDtp) continue;
          visited.add(next);
          queue.push({
            id: next,
            hops: cur.hops + 1,
            path: direction === "in" ? [next, ...cur.path] : [...cur.path, next],
          });
        }
      }
    };
    visible.forEach((id) => {
      walk(id, "in");
      walk(id, "out");
    });
    return found;
  }

  incoming(id: string): GraphEdge[] {
    return this.inAdj.get(id) || [];
  }

  outgoing(id: string): GraphEdge[] {
    return this.outAdj.get(id) || [];
  }

  isEmpty(n: GraphNode): boolean {
    return isEmptyObject(n);
  }

  rebuild(filters: UiFilters): GraphFrame {
    const allowed = new Set(this.graph.nodes
      .filter((n) => this.wanted(n, filters))
      .filter((n) => filters.showAllCv || n.type !== "calcview" || this.cvHasConsumer(n.id))
      .filter((n) => !filters.hideNeverDtp || n.type !== "dtp" || !this.isNeverDtp(n))
      .map((n) => n.id));
    const seed = filters.seedId && this.nodeById[filters.seedId] ? filters.seedId : "";
    if (seed) allowed.add(seed);
    const focus = seed
      ? new Set([seed])
      : (filters.query ? new Set(this.matchSeeds(filters.query, allowed)) : new Set<string>());
    let landscape = new Set(allowed);
    if (filters.hideLiveDtp && !filters.query) {
      landscape = new Set();
      for (const row of this.stalePairs) {
        if (allowed.has(row.sid)) landscape.add(row.sid);
        if (allowed.has(row.tid)) landscape.add(row.tid);
      }
    }
    let bundle = new Set<string>();
    if (focus.size) {
      bundle = this.traverse(
        [...focus],
        filters.egoDepth,
        filters.egoParents,
        filters.egoChildren,
        allowed,
        filters.showFrozenLoads,
        filters.hideNeverDtp,
      );
      bundle = new Set([...bundle].filter((id) => allowed.has(id)));
    }
    const edgeScope = bundle.size ? bundle : landscape;
    let edges = this.graph.edges.filter((edge) =>
      edgeScope.has(edge.source) && edgeScope.has(edge.target) &&
      (filters.showFrozenLoads || !this.loadsIntoFrozenData(this.nodeById[edge.source], this.nodeById[edge.target], edge.type)) &&
      (!filters.hideNeverDtp || !this.isNeverLoadEdge(edge)));
    const viaScope = bundle.size ? bundle : edgeScope;
    let vias: ViaEdge[] = [];
    let viaPending = false;
    if (viaScope.size && (bundle.size > 0 || viaScope.size <= 280)) {
      vias = this.collapsedVias(viaScope, filters.showFrozenLoads, filters.hideNeverDtp);
    } else if (viaScope.size > 280) {
      viaPending = true;
    }
    if (filters.hideNeverDtp) {
      vias = vias.filter((edge) => !this.isNeverDtpPath(edge.path, edge.source, edge.target));
    }
    if (filters.hideLiveDtp) {
      vias = vias.filter((edge) => this.isStaleDtpPath(edge.path, edge.source, edge.target));
      edges = edges.filter((edge) => this.isStaleLoadEdge(edge));
    }
    const viaPairs = new Set(vias.map((v) => `${v.source}|${v.target}`));
    edges = edges.filter((edge) => {
      if (!LOAD_EDGES.has(edge.type)) return true;
      return !viaPairs.has(`${edge.source}|${edge.target}`);
    });
    const visible = bundle.size ? new Set(bundle) : new Set(landscape);
    if (!visible.size) {
      for (const id of allowed) visible.add(id);
    }
    edges = edges.filter((edge) => visible.has(edge.source) && visible.has(edge.target));
    vias = vias.filter((edge) => visible.has(edge.source) && visible.has(edge.target));
    return { visible, focus, bundle, edges, vias, isolated: 0, viaPending };
  }

  computeVias(visible: Set<string>, filters: UiFilters): ViaEdge[] {
    let vias = this.collapsedVias(visible, filters.showFrozenLoads, filters.hideNeverDtp);
    if (filters.hideNeverDtp) {
      vias = vias.filter((edge) => !this.isNeverDtpPath(edge.path, edge.source, edge.target));
    }
    if (filters.hideLiveDtp) {
      vias = vias.filter((edge) => this.isStaleDtpPath(edge.path, edge.source, edge.target));
    }
    return vias.filter((edge) => visible.has(edge.source) && visible.has(edge.target));
  }
}
