import { Graphics, Rectangle } from "pixi.js";
import type { Container, Text } from "pixi.js";
import { BevelFilter } from "pixi-filters/bevel";

export type ShockKind = "small" | "full";

interface NodeFade {
  root: Container;
  label: Text;
  t: number;
  duration: number;
  onDone?: () => void;
}

interface NodeFlash {
  root: Container;
  label: Text;
  t: number;
  duration: number;
  baseScale: number;
}

interface NodeEnter {
  root: Container;
  label: Text;
  t: number;
  duration: number;
}

interface NodeMove {
  root: Container;
  label: Text;
  fromX: number;
  fromY: number;
  toX: number;
  toY: number;
  t: number;
  duration: number;
  onStep?: () => void;
  onDone?: () => void;
}

export class GraphFx {
  readonly bevel = new BevelFilter({
    rotation: 40,
    thickness: 3.2,
    lightColor: 0xfff3d6,
    lightAlpha: 0.85,
    shadowColor: 0x101418,
    shadowAlpha: 0.55,
  });

  private readonly ink = new Graphics({ eventMode: "none" });
  private flicker: { node: Container; baseAlpha: number; t: number } | null = null;
  private bevelHost: Container | null = null;
  private fades: NodeFade[] = [];
  private flashes: NodeFlash[] = [];
  private enters: NodeEnter[] = [];
  private moves: NodeMove[] = [];
  private shockAge = -1;
  private shockDuration = 0.85;
  private originX = 0;
  private originY = 0;
  private startR = 10;
  private endR = 80;
  private strokeW = 2;
  private waveColor = 0xffe08a;

  get busy(): boolean {
    return this.shockAge >= 0 || !!this.flicker || this.fades.length > 0 || this.flashes.length > 0
      || this.enters.length > 0 || this.moves.length > 0;
  }

  get hasExits(): boolean {
    return this.fades.length > 0;
  }

  attach(world: Container, context: Container, path: Container): void {
    world.filters = [];
    world.filterArea = undefined;
    context.filters = [];
    path.filters = [];
  }

  setOverlay(overlay: Container): void {
    overlay.eventMode = "none";
    overlay.zIndex = 20000;
  }

  setFocusMode(_on: boolean, path: Container): void {
    path.filters = [];
  }

  setFilterArea(_world: Container, _screen: Rectangle): void {}

  clearContentFilters(): void {}

  /** Уходящие узлы — только прозрачность, без blur. */
  startNodeExit(root: Container, label: Text, onDone?: () => void): void {
    root.eventMode = "none";
    label.eventMode = "none";
    root.filters = [];
    this.fades.push({ root, label, t: 0, duration: 0.22, onDone });
  }

  /** Остающиеся в подграфе — короткая вспышка ~1 с. */
  startNodeFlash(root: Container, label: Text, duration = 1): void {
    this.flashes.push({
      root,
      label,
      t: 0,
      duration,
      baseScale: root.scale.x || 1,
    });
  }

  startNodeEnter(root: Container, label: Text): void {
    root.alpha = 0;
    label.alpha = 0;
    this.enters.push({ root, label, t: 0, duration: 0.22 });
  }

  startNodeMove(
    root: Container,
    label: Text,
    toX: number,
    toY: number,
    duration = 1.1,
    onStep?: () => void,
    onDone?: () => void,
  ): void {
    const dx = root.x - toX;
    const dy = root.y - toY;
    if (Math.hypot(dx, dy) < 1) {
      root.x = toX;
      root.y = toY;
      onStep?.();
      onDone?.();
      return;
    }
    this.moves.push({
      root,
      label,
      fromX: root.x,
      fromY: root.y,
      toX,
      toY,
      t: 0,
      duration,
      onStep,
      onDone,
    });
  }

  clearNodeMoves(): void {
    this.moves = [];
  }

  clearNodeAnimations(): void {
    for (const fade of this.fades) {
      fade.root.filters = [];
      fade.label.destroy();
      fade.root.destroy({ children: true });
    }
    this.fades = [];
    for (const flash of this.flashes) {
      flash.root.alpha = 1;
      flash.label.alpha = 1;
      flash.root.scale.set(flash.baseScale);
    }
    this.flashes = [];
    this.enters = [];
    this.moves = [];
  }

  startShock(
    world: Container,
    worldX: number,
    worldY: number,
    kind: ShockKind,
    nodeRadius: number,
    cameraScale: number,
    color: number,
  ): number {
    this.stopShock();
    const full = kind === "full";
    const scale = Math.max(cameraScale, 0.08);
    this.shockDuration = full ? 0.34 : 0.24;
    this.startR = nodeRadius + 3;
    this.endR = nodeRadius + (full ? 90 : 55) / scale;
    this.strokeW = Math.max(1.2, 2.2 / scale);
    this.waveColor = color;
    this.originX = worldX;
    this.originY = worldY;
    this.shockAge = 0;
    this.ink.eventMode = "none";
    this.ink.zIndex = 400;
    world.addChild(this.ink);
    this.draw(0);
    return this.shockDuration * 1000;
  }

  stopShock(): void {
    this.ink.clear();
    this.ink.parent?.removeChild(this.ink);
    this.shockAge = -1;
  }

  startFlicker(node: Container): void {
    this.flicker = { node, baseAlpha: node.alpha, t: 0 };
  }

  attachBevel(node: Container): void {
    this.detachBevel();
    this.bevelHost = node;
    node.filters = [this.bevel];
  }

  detachBevel(): void {
    if (!this.bevelHost) return;
    this.bevelHost.filters = [];
    this.bevelHost = null;
  }

  tick(deltaMS: number): void {
    const dt = deltaMS / 1000;
    if (this.shockAge >= 0) {
      this.shockAge += dt;
      const t = Math.min(1, this.shockAge / this.shockDuration);
      this.draw(t);
      if (t >= 1) this.stopShock();
    }
    if (this.flicker) {
      this.flicker.t += dt;
      const pulse = 0.88 + 0.12 * Math.abs(Math.sin(this.flicker.t * 10));
      this.flicker.node.alpha = this.flicker.baseAlpha * pulse;
      if (this.flicker.t > 0.28) {
        this.flicker.node.alpha = this.flicker.baseAlpha;
        this.flicker = null;
      }
    }
    if (this.fades.length) {
      const done: NodeFade[] = [];
      for (const fade of this.fades) {
        fade.t += dt / fade.duration;
        const e = Math.min(1, fade.t);
        const alpha = 1 - e;
        fade.root.alpha = alpha;
        fade.label.alpha = alpha;
        if (e >= 1) done.push(fade);
      }
      for (const fade of done) {
        this.fades.splice(this.fades.indexOf(fade), 1);
        fade.onDone?.();
        fade.label.destroy();
        fade.root.destroy({ children: true });
      }
    }
    if (this.flashes.length) {
      const done: NodeFlash[] = [];
      for (const flash of this.flashes) {
        flash.t += dt;
        const e = Math.min(1, flash.t / flash.duration);
        const wave = Math.sin(e * Math.PI * 2.8);
        const boost = (1 - e * 0.55) * Math.max(0, wave);
        flash.root.alpha = 0.82 + 0.18 * (1 + boost);
        flash.label.alpha = flash.root.alpha;
        flash.root.scale.set(flash.baseScale * (1 + 0.07 * boost));
        if (e >= 1) done.push(flash);
      }
      for (const flash of done) {
        this.flashes.splice(this.flashes.indexOf(flash), 1);
        flash.root.alpha = 1;
        flash.label.alpha = 1;
        flash.root.scale.set(flash.baseScale);
      }
    }
    if (this.enters.length) {
      const done: NodeEnter[] = [];
      for (const enter of this.enters) {
        enter.t += dt / enter.duration;
        const e = Math.min(1, enter.t);
        const ease = 1 - (1 - e) * (1 - e);
        enter.root.alpha = ease;
        enter.label.alpha = ease;
        if (e >= 1) done.push(enter);
      }
      for (const enter of done) {
        this.enters.splice(this.enters.indexOf(enter), 1);
        enter.root.alpha = 1;
        enter.label.alpha = 1;
      }
    }
    if (this.moves.length) {
      const done: NodeMove[] = [];
      for (const move of this.moves) {
        move.t += dt / move.duration;
        const e = Math.min(1, move.t);
        const ease = e < 0.5 ? 4 * e * e * e : 1 - (-2 * e + 2) ** 3 / 2;
        move.root.x = move.fromX + (move.toX - move.fromX) * ease;
        move.root.y = move.fromY + (move.toY - move.fromY) * ease;
        move.onStep?.();
        if (e >= 1) done.push(move);
      }
      for (const move of done) {
        this.moves.splice(this.moves.indexOf(move), 1);
        move.root.x = move.toX;
        move.root.y = move.toY;
        move.onStep?.();
        move.onDone?.();
      }
    }
  }

  private draw(t: number): void {
    const expand = Math.min(1, t / 0.52);
    const easeOut = 1 - (1 - expand) * (1 - expand);
    const fade = Math.pow(Math.max(0, 1 - t / 0.68), 2.6);
    const r = this.startR + (this.endR - this.startR) * easeOut;
    this.ink.clear();
    this.ink.circle(this.originX, this.originY, r)
      .stroke({ width: this.strokeW, color: this.waveColor, alpha: 0.42 * fade });
  }
}
