import { GraphModel } from "../graph/model";
import { MUTED, PREFIX_COLORS, fmtDate } from "../graph/semantics";
import type { GraphFrame, UiFilters } from "../graph/types";
import { nodeDetailHtml, type GraphView } from "../scene/graphView";

export function el<T extends HTMLElement>(id: string): T {
  const node = document.getElementById(id);
  if (!node) throw new Error(`#${id} missing`);
  return node as T;
}

export function readFilters(model: GraphModel): UiFilters {
  const enabledTypes = new Set<string>();
  for (const type of model.types) {
    const box = document.getElementById(`t_${type}`) as HTMLInputElement | null;
    if (box?.checked) enabledTypes.add(type);
  }
  return {
    query: el<HTMLInputElement>("q").value.trim(),
    prefix: "",
    egoDepth: Number(el<HTMLSelectElement>("egoDepth").value || 2),
    egoParents: el<HTMLInputElement>("egoParents").checked,
    egoChildren: el<HTMLInputElement>("egoChildren").checked,
    showFrozenLoads: el<HTMLInputElement>("showFrozenLoads").checked,
    showAllCv: el<HTMLInputElement>("showAllCv").checked,
    hideLiveDtp: el<HTMLInputElement>("hideLiveDtp").checked,
    hideNeverDtp: el<HTMLInputElement>("hideNeverDtp").checked,
    enabledTypes,
  };
}

export function fillStaticChrome(model: GraphModel): void {
  const typeBox = el("types");
  const defaults = model.defaultFilters();
  model.types.forEach((type) => {
    typeBox.insertAdjacentHTML(
      "beforeend",
      `<label class="chk"><input type="checkbox" id="t_${type}" ${defaults.enabledTypes.has(type) ? "checked" : ""}/>${type}</label>`,
    );
  });
  const legend = document.getElementById("legend");
  if (legend) {
    legend.innerHTML = Object.keys(PREFIX_COLORS).map((p) =>
      `<label class="chk"><span class="dot" style="background:${PREFIX_COLORS[p]}"></span>${p}</label>`).join("") +
      `<label class="chk"><span class="dot" style="background:${MUTED}"></span>тех / куб / без префикса</label>` +
      `<label class="chk"><span class="dot" style="background:#7a8490;outline:1px solid #7dd3f0"></span>FROZEN — цвет префикса, голубая рамка</label>` +
      `<label class="chk"><span class="dot" style="background:#4e1530;outline:1px solid #7dd3f0"></span>пустой — тёмно-малиновый, та же рамка</label>`;
  }
  const legendShape = document.getElementById("legendShape");
  if (legendShape) {
    legendShape.innerHTML =
      `<label class="chk">● ODSO / ADSO — цвет префикса, площадь ≈ GB</label>` +
      `<label class="chk">● светлый — virtual table (SDA)</label>` +
      `<label class="chk">● FROZEN — заливка по префиксу, тонкая голубая рамка</label>` +
      `<label class="chk">● пустой — тёмно-малиновый, та же голубая рамка</label>` +
      `<label class="chk">→ обычная стрелка — прямая связь</label>` +
      `<label class="chk">⇢ золотой пунктир — живая загрузка через скрытые объекты</label>` +
      `<label class="chk">⇢ тёмно-голубой — ребро в архивный, темнее рамки</label>` +
      `<label class="chk">⇢ 枯色 / соломенный — stale, давно не грузился</label>` +
      `<label class="chk">⇢ 鼠色 / серый — never, DTP ни разу не грузился</label>`;
  }
}

export function showNodeDetail(model: GraphModel, id: string): void {
  const detail = el("detailBody");
  const edges = el("edgesBody");
  const { html, edgesHtml } = nodeDetailHtml(model, id);
  detail.classList.remove("stale-ink", "never-ink");
  edges.classList.remove("stale-ink", "never-ink");
  detail.innerHTML = html;
  edges.innerHTML = edgesHtml;
}

export function showEdgeDetail(payload: {
  title: string;
  lastOk: string;
  path: string;
  stale: boolean;
  never: boolean;
}): void {
  const detail = el("detailBody");
  const edges = el("edgesBody");
  detail.classList.toggle("stale-ink", payload.stale);
  detail.classList.toggle("never-ink", payload.never && !payload.stale);
  edges.classList.remove("stale-ink", "never-ink");
  detail.innerHTML =
    `<p><b>${payload.title}</b></p>` +
    `<p class="meta">последняя живая DTP (строки или зелёный): ${fmtDate(payload.lastOk)}</p>` +
    (payload.path ? `<p class="meta">${payload.path.replace(/</g, "")}</p>` : "");
  edges.innerHTML = `<p class="meta">выбрано ребро</p>`;
}

export function fillVisibleList(model: GraphModel, frame: GraphFrame, view: GraphView): void {
  const ul = el("visibleList");
  const items = [...(frame.bundle.size ? frame.bundle : frame.visible)]
    .map((id) => model.nodeById[id])
    .filter(Boolean)
    .sort((a, b) => String(a.name).localeCompare(String(b.name)));
  if (items.length > 80) {
    ul.innerHTML = `<li class="meta">на экране ${items.length} узлов — введите имя слева, чтобы увидеть наименования пучка</li>`;
    return;
  }
  ul.innerHTML = items.map((n) => {
    return `<li data-id="${n.id.replace(/"/g, "")}"><div class="tech">${(n.label || n.name).replace(/</g, "")}</div>${
      n.txtlg ? `<div class="txtlg">${n.txtlg.replace(/</g, "")}</div>` : ""
    }</li>`;
  }).join("");
  ul.querySelectorAll("li[data-id]").forEach((li) => {
    const id = li.getAttribute("data-id") || "";
    (li as HTMLElement).onclick = () => {
      view.selectNode(id);
      showNodeDetail(model, id);
      highlightVisible(id);
    };
    (li as HTMLElement).ondblclick = () => {
      view.hooks.onNodeFocus(id);
    };
  });
}

export function highlightVisible(id: string): void {
  const ul = document.getElementById("visibleList");
  if (!ul) return;
  ul.querySelectorAll("li[data-id]").forEach((li) => {
    const on = li.getAttribute("data-id") === id;
    li.classList.toggle("on", on);
    if (on) (li as HTMLElement).scrollIntoView({ block: "nearest" });
  });
}

export function setRendererBadge(info: { label: string; ok: boolean }): void {
  const badge = el("glBadge");
  badge.textContent = info.label;
  badge.classList.toggle("ok", info.ok);
  badge.classList.toggle("warn-badge", !info.ok);
}

export function setFpsBadge(fps: number, idle = false): void {
  const badge = el("fpsBadge");
  badge.textContent = idle ? "pause" : `${Math.round(fps)} fps`;
  badge.title = idle ? "Рендер на паузе — GPU не крутит пустой цикл" : "";
  badge.classList.toggle("idle-badge", idle);
}

export function updateHeader(model: GraphModel, frame: GraphFrame): void {
  const counts = (model.graph.meta && model.graph.meta.counts) || {};
  const stale = frame.vias.filter((v) => model.isStaleDtpPath(v.path, v.source, v.target)).length;
  el("hdrMeta").textContent =
    `${frame.visible.size} на экране` +
    `${frame.bundle.size ? ` · пучок ${frame.bundle.size}` : ""} · via ${frame.vias.length}` +
    `${frame.viaPending ? " · via считаются…" : ""} · stale ${stale}` +
    `${frame.isolated ? ` · скрыто изолир. ${frame.isolated}` : ""}` +
    ` · всего ${counts.nodes || 0} узлов / ${counts.edges || 0} рёбер · Pixi`;
}

function escCrumb(s: string): string {
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/"/g, "&quot;");
}

/** Хлебные крошки: путь double-click по графу. index −1 = «Весь граф». */
export function renderBreadcrumbs(
  model: GraphModel,
  crumbs: string[],
  onNavigate: (index: number) => void,
): void {
  const nav = el("graphCrumbs");
  if (!crumbs.length) {
    nav.hidden = true;
    nav.innerHTML = "";
    return;
  }
  nav.hidden = false;
  const parts: string[] = [`<button type="button" class="crumb" data-idx="-1">Весь граф</button>`];
  crumbs.forEach((id, i) => {
    const n = model.nodeById[id];
    const label = escCrumb(String(n?.label || n?.name || id));
    parts.push('<span class="crumb-sep" aria-hidden="true">›</span>');
    if (i === crumbs.length - 1) {
      parts.push(`<span class="crumb-current" title="${label}">${label}</span>`);
    } else {
      parts.push(`<button type="button" class="crumb" data-idx="${i}" title="${label}">${label}</button>`);
    }
  });
  nav.innerHTML = parts.join("");
  nav.querySelectorAll("button.crumb").forEach((btn) => {
    btn.addEventListener("click", () => {
      const idx = Number(btn.getAttribute("data-idx"));
      onNavigate(Number.isFinite(idx) ? idx : -1);
    });
  });
  const wrap = document.getElementById("graphWrap");
  if (wrap) {
    requestAnimationFrame(() => {
      wrap.style.setProperty(
        "--graph-header",
        `${wrap.querySelector<HTMLElement>(".graph-chrome")?.offsetHeight ?? 44}px`,
      );
    });
  }
}

export function bindFilterEvents(model: GraphModel, onChange: () => void): void {
  const q = el<HTMLInputElement>("q");
  let timer = 0;
  bindSearchSuggest(model);
  document.querySelectorAll("#types input[type=checkbox]").forEach((box) => {
    box.addEventListener("change", onChange);
  });
  ["egoDepth", "egoParents", "egoChildren", "showFrozenLoads", "showAllCv", "hideLiveDtp", "hideNeverDtp"]
    .forEach((id) => el(id).addEventListener("change", onChange));
  q.addEventListener("input", () => {
    window.clearTimeout(timer);
    timer = window.setTimeout(onChange, 220);
  });
}

interface SearchItem {
  value: string;
  title: string;
  sub?: string;
}

function escSuggest(s: string): string {
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/"/g, "&quot;");
}

function searchItems(model: GraphModel): SearchItem[] {
  return model.graph.nodes
    .filter((n) => ["odso", "adso", "cube", "vtable", "datasource", "hcpr", "calcview"].includes(n.type))
    .sort((a, b) => a.name.localeCompare(b.name))
    .map((n) => {
      const value = String(n.name);
      const title = value;
      const txt = n.txtlg?.trim();
      const sub = txt && txt !== value ? txt : (n.label && n.label !== value ? String(n.label) : undefined);
      return { value, title, sub };
    });
}

function rankSearchItem(item: SearchItem, needle: string): number {
  const name = item.value.toLowerCase();
  const sub = (item.sub || "").toLowerCase();
  if (name === needle) return 0;
  if (name.startsWith(needle)) return 1;
  if (sub === needle) return 2;
  if (sub.startsWith(needle)) return 3;
  if (name.includes(needle)) return 4;
  if (sub.includes(needle)) return 5;
  return 99;
}

function bindSearchSuggest(model: GraphModel): void {
  const q = el<HTMLInputElement>("q");
  const list = el<HTMLUListElement>("qSuggest");
  const wrap = q.closest(".search-wrap") || q.parentElement;
  const items = searchItems(model);
  let active = -1;
  let visible: SearchItem[] = [];

  const setOpen = (open: boolean) => {
    q.setAttribute("aria-expanded", open ? "true" : "false");
  };

  const hide = () => {
    list.hidden = true;
    active = -1;
    setOpen(false);
  };

  const render = () => {
    list.innerHTML = visible.map((item, i) => {
      const cls = i === active ? "active" : "";
      const sub = item.sub ? `<span class="muted-bit">${escSuggest(item.sub)}</span>` : "";
      return `<li role="option" data-idx="${i}" class="${cls}">${escSuggest(item.title)}${sub ? ` ${sub}` : ""}</li>`;
    }).join("");
    const open = visible.length > 0;
    list.hidden = !open;
    setOpen(open);
  };

  const findExact = (raw: string): SearchItem | undefined => {
    const needle = raw.trim().toLowerCase();
    if (!needle) return undefined;
    return items.find((item) => item.value.toLowerCase() === needle);
  };

  const filter = () => {
    const raw = q.value.trim();
    const needle = raw.toLowerCase();
    const exact = findExact(raw);
    if (exact) {
      const changed = q.value !== exact.value;
      if (changed) q.value = exact.value;
      hide();
      if (changed) q.dispatchEvent(new Event("input", { bubbles: true }));
      return;
    }
    if (!needle) {
      visible = items.slice(0, 10);
    } else {
      visible = items
        .filter((item) => {
          const hay = `${item.value} ${item.sub || ""}`.toLowerCase();
          return hay.includes(needle);
        })
        .sort((a, b) => rankSearchItem(a, needle) - rankSearchItem(b, needle))
        .slice(0, 12);
    }
    active = -1;
    render();
  };

  const pick = (item: SearchItem) => {
    q.value = item.value;
    hide();
    q.dispatchEvent(new Event("input", { bubbles: true }));
  };

  q.addEventListener("focus", filter);
  q.addEventListener("input", filter);
  q.addEventListener("keydown", (ev) => {
    if (ev.key === "ArrowDown") {
      if (list.hidden) filter();
      if (!visible.length) return;
      ev.preventDefault();
      active = active < 0 ? 0 : Math.min(active + 1, visible.length - 1);
      render();
      return;
    }
    if (ev.key === "ArrowUp") {
      if (list.hidden || !visible.length) return;
      ev.preventDefault();
      active = active < 0 ? visible.length - 1 : Math.max(active - 1, 0);
      render();
      return;
    }
    if (ev.key === "Enter") {
      const exact = findExact(q.value);
      if (exact) {
        ev.preventDefault();
        pick(exact);
        return;
      }
      if (!list.hidden && active >= 0 && visible[active]) {
        ev.preventDefault();
        pick(visible[active]);
      }
      return;
    }
    if (ev.key === "Escape") hide();
  });

  list.addEventListener("mousedown", (ev) => {
    ev.preventDefault();
  });
  list.addEventListener("click", (ev) => {
    ev.stopPropagation();
    const li = (ev.target as HTMLElement).closest("li[data-idx]");
    if (!li) return;
    const idx = Number(li.getAttribute("data-idx"));
    if (Number.isFinite(idx) && visible[idx]) pick(visible[idx]);
  });

  document.addEventListener("mousedown", (ev) => {
    if (!wrap?.contains(ev.target as Node)) hide();
  });
}
