import { Application, Rectangle } from "pixi.js";
import "./styles.css";
import { loadSnapshots } from "./data/loadSnapshots";
import { GraphModel } from "./graph/model";
import { GraphView } from "./scene/graphView";
import {
  bindFilterEvents,
  el,
  fillStaticChrome,
  fillVisibleList,
  readFilters,
  setFpsBadge,
  setRendererBadge,
  highlightVisible,
  showEdgeDetail,
  showNodeDetail,
  updateHeader,
  renderBreadcrumbs,
} from "./ui/chrome";
import { bindFloatPanels, bindGraphHeader } from "./ui/floatPanels";

function yieldToMain(): Promise<void> {
  return new Promise((resolve) => {
    requestAnimationFrame(() => requestAnimationFrame(() => resolve()));
  });
}

(async () => {
  const boot = el("boot");
  boot.textContent = "загрузка снимка…";
  if (document.fonts?.load) {
    document.fonts.load("400 13px 'Segoe UI'").catch(() => undefined);
  }
  const snapshots = await loadSnapshots();
  const model = new GraphModel(snapshots);
  fillStaticChrome(model);
  bindFloatPanels();
  bindGraphHeader();

  const host = el("graph");
  const app = new Application();
  await app.init({
    resizeTo: host,
    background: 0x000000,
    antialias: true,
    autoDensity: true,
    autoStart: true,
    bezierSmoothness: 1,
    resolution: Math.min(2, Math.max(1, window.devicePixelRatio || 1)),
    preference: ["webgpu", "webgl"],
    webgpu: {
      powerPreference: "high-performance",
    },
    webgl: {
      preferWebGLVersion: 2,
      useBackBuffer: false,
      powerPreference: "high-performance",
    },
  });
  host.appendChild(app.canvas);
  setRendererBadge(inspectRenderer(app));
  app.resize();
  app.stage.eventMode = "static";
  app.stage.hitArea = app.screen;

  let view: GraphView;
  const crumbs: string[] = [];
  let applying = false;

  const setBusy = (msg: string | null) => {
    if (msg) {
      boot.textContent = msg;
      boot.hidden = false;
    } else {
      boot.hidden = true;
    }
  };

  const syncCrumbs = () => renderBreadcrumbs(model, crumbs, navigateCrumb);

  const apply = (fit = true, seedId = "", incremental = false) => {
    try {
      const filters = readFilters(model);
      if (seedId) filters.seedId = seedId;
      if (!seedId) crumbs.length = 0;
      const frame = incremental && seedId
        ? view.rebuild(filters, { incremental: true, seedId, fit: false })
        : view.rebuild(filters, fit);
      if (incremental) {
        requestAnimationFrame(() => fillVisibleList(model, frame, view));
        requestAnimationFrame(() => updateHeader(model, frame));
      } else {
        fillVisibleList(model, frame, view);
        updateHeader(model, frame);
      }
      syncCrumbs();
    } catch (err) {
      console.error(err);
      boot.textContent = `ошибка загрузки: ${err instanceof Error ? err.message : String(err)}`;
      boot.hidden = false;
    }
  };

  const applyAsync = async (fit = true, seedId = "", incremental = false, busyMsg = "перестройка…") => {
    if (applying) return;
    applying = true;
    setBusy(busyMsg);
    view.wake();
    await yieldToMain();
    try {
      apply(fit, seedId, incremental);
    } finally {
      applying = false;
      setBusy(null);
      view.requestRender();
    }
  };

  const navigateCrumb = (index: number) => {
    if (index < 0) {
      crumbs.length = 0;
      syncCrumbs();
      el<HTMLInputElement>("q").value = "";
      view.clearSelection();
      void applyAsync(true, "", false, "весь граф…");
      return;
    }
    const id = crumbs[index];
    if (!id) return;
    crumbs.length = index + 1;
    syncCrumbs();
    focusNode(id, { fromBreadcrumb: true });
  };

  let lastFocusAt = 0;
  let lastFocusId = "";
  let focusing = false;
  const focusNode = async (id: string, opts?: { fromBreadcrumb?: boolean }) => {
    const node = model.nodeById[id];
    if (!node) return;
    const now = performance.now();
    if (!opts?.fromBreadcrumb && id === lastFocusId && now - lastFocusAt < 600) return;
    if (focusing) return;
    lastFocusAt = now;
    lastFocusId = id;
    if (!opts?.fromBreadcrumb) {
      const existing = crumbs.indexOf(id);
      if (existing >= 0) crumbs.length = existing + 1;
      else crumbs.push(id);
    }
    el<HTMLInputElement>("q").value = node.name;
    showNodeDetail(model, id);
    focusing = true;
    setBusy("фокус…");
    view.wake();
    await yieldToMain();
    try {
      apply(false, id, true);
      await view.whenIncrementalReady();
      view.selectNode(id);
      highlightVisible(id);
      syncCrumbs();
    } finally {
      focusing = false;
      setBusy(null);
      view.requestRender();
    }
  };

  view = new GraphView(app, model, {
    onNodeSelect(id) {
      showNodeDetail(model, id);
      highlightVisible(id);
    },
    onNodeFocus(id) {
      focusNode(id);
    },
    onEdgeSelect(_kind, payload) {
      showEdgeDetail(payload);
    },
    onFrame(frame) {
      updateHeader(model, frame);
    },
  });

  view.bindTooltip(el("nodeTip"));

  bindFilterEvents(model, () => { void applyAsync(true); });
  el("fitBtn").onclick = () => view.fit();
  el("relayout").onclick = () => { void applyAsync(true); };

  const mapClient = (ev: PointerEvent | MouseEvent) => {
    const point = { x: 0, y: 0 };
    app.renderer.events.mapPositionToPoint(point, ev.clientX, ev.clientY);
    return point;
  };

  app.canvas.addEventListener("click", (ev) => {
    if (view.didDrag() || view.didPinch()) return;
    const point = mapClient(ev);
    const bodyId = view.hitNodeBodyAt(point.x, point.y);
    if (bodyId) {
      view.selectNode(bodyId);
      showNodeDetail(model, bodyId);
      highlightVisible(bodyId);
      view.playShock(bodyId, "small");
      return;
    }
    const link = view.hitLinkAt(point.x, point.y);
    if (link) {
      view.describeLink(link);
      return;
    }
    const labelId = view.hitNodeLabelAt(point.x, point.y);
    if (!labelId) return;
    view.selectNode(labelId);
    showNodeDetail(model, labelId);
    highlightVisible(labelId);
    view.playShock(labelId, "small");
  });

  app.canvas.addEventListener("dblclick", (ev) => {
    ev.preventDefault();
    if (view.consumeFocusHandled()) return;
    const point = mapClient(ev);
    const id = view.hitNodeAt(point.x, point.y) || view.lastTouchedNode();
    if (!id) return;
    void focusNode(id);
  });

  const syncHitArea = () => {
    app.stage.hitArea = new Rectangle(0, 0, app.screen.width, app.screen.height);
    view.fx.setFilterArea(view.world, app.screen);
    view.requestRender();
  };
  window.addEventListener("resize", syncHitArea);
  if (typeof ResizeObserver !== "undefined") {
    new ResizeObserver(syncHitArea).observe(host);
  }

  await applyAsync(true, "", false, "загрузка снимка…");
  setBusy(null);

  let fpsAt = 0;
  app.ticker.add(() => {
    const now = performance.now();
    if (now - fpsAt < 250) return;
    fpsAt = now;
    setFpsBadge(app.ticker.started ? app.ticker.FPS : 0, view.isTickerIdle());
  });
})().catch((err) => {
  const boot = document.getElementById("boot");
  if (boot) boot.textContent = `ошибка загрузки: ${err instanceof Error ? err.message : String(err)}`;
  console.error(err);
});

function inspectRenderer(app: Application): { label: string; ok: boolean } {
  const name = String(app.renderer.name || "unknown").toLowerCase();
  if (name === "webgpu") return { label: "WebGPU", ok: true };
  const ctx = (app.renderer as { context?: { webGLVersion?: number; gl?: WebGLRenderingContext } }).context;
  const version = ctx?.webGLVersion;
  const gl = ctx?.gl;
  const webgl2 =
    version === 2 ||
    (typeof WebGL2RenderingContext !== "undefined" && !!gl && gl instanceof WebGL2RenderingContext);
  if (webgl2) return { label: "WebGL2", ok: true };
  if (name === "webgl") return { label: "WebGL1", ok: false };
  return { label: name.toUpperCase(), ok: false };
}
