export interface GraphViewHooks {
  onNodeSelect(id: string): void;
  onNodeFocus(id: string): void;
  onFrame?(frame: GraphFrame): void;
  onEdgeSelect(kind: "edge" | "via", payload: {
    title: string;
    lastOk: string;
    path: string;
    stale: boolean;
    never: boolean;
  }): void;
}

interface NodeSprite {
  id: string;
  node: GraphNode;
  root: Container;
  body: Graphics;
  radius: number;
  label: Text;
}

interface QuadCurve {
  x1: number;
  y1: number;
  cx: number;
  cy: number;
  x2: number;
  y2: number;
}

interface CurveMeta {
  source: string;
  target: string;
  offset: number;
}

function quadPoint(c: QuadCurve, t: number): { x: number; y: number } {
  const u = 1 - t;
  return {
    x: u * u * c.x1 + 2 * u * t * c.cx + t * t * c.x2,
    y: u * u * c.y1 + 2 * u * t * c.cy + t * t * c.y2,
  };
}

function strokeQuad(g: Graphics, c: QuadCurve, color: number, alpha: number, width: number): void {
  g.moveTo(c.x1, c.y1).quadraticCurveTo(c.cx, c.cy, c.x2, c.y2).stroke({ width, color, alpha });
}

function strokeQuadRange(
  g: Graphics,
  c: QuadCurve,
  t0: number,
  t1: number,
  color: number,
  alpha: number,
  width: number,
): void {
  const lo = Math.max(0, Math.min(t0, t1));
  const hi = Math.min(1, Math.max(t0, t1));
  if (hi - lo < 0.01) return;
  const steps = Math.max(6, Math.ceil((hi - lo) * 28));
  const p0 = quadPoint(c, lo);
  g.moveTo(p0.x, p0.y);
  for (let i = 1; i <= steps; i++) {
    const p = quadPoint(c, lo + ((hi - lo) * i) / steps);
    g.lineTo(p.x, p.y);
  }
  g.stroke({ width, color, alpha });
}

function dashedQuadRange(
  g: Graphics,
  c: QuadCurve,
  t0: number,
  t1: number,
  dash: number, gap: number,
  color: number, alpha: number, width: number,
): void {
  const lo = Math.max(0, Math.min(t0, t1));
  const hi = Math.min(1, Math.max(t0, t1));
  if (hi - lo < 0.01) return;
  const mid = quadPoint(c, (lo + hi) * 0.5);
  const end = quadPoint(c, hi);
  const chord = Math.hypot(end.x - quadPoint(c, lo).x, end.y - quadPoint(c, lo).y)
    + Math.hypot(end.x - mid.x, end.y - mid.y);
  const steps = Math.max(12, Math.ceil(chord / 7));
  let drawn = 0;
  let on = true;
  let prev = quadPoint(c, lo);
  for (let i = 1; i <= steps; i++) {
    const t = lo + ((hi - lo) * i) / steps;
    const p = quadPoint(c, t);
    const seg = Math.hypot(p.x - prev.x, p.y - prev.y);
    if (on) g.moveTo(prev.x, prev.y).lineTo(p.x, p.y).stroke({ width, color, alpha });
    drawn += seg;
    const limit = on ? dash : gap;
    if (drawn >= limit) {
      drawn = 0;
      on = !on;
    }
    prev = p;
  }
}

function arrowHead(g: Graphics, x1: number, y1: number, x2: number, y2: number, color: number, alpha: number): void {
  const dx = x2 - x1;
  const dy = y2 - y1;
  const len = Math.hypot(dx, dy) || 1;
  const ux = dx / len;
  const uy = dy / len;
  const s = 3.5;
  g.moveTo(x2, y2)
    .lineTo(x2 - ux * s + uy * 3.4, y2 - uy * s - ux * 3.4)
    .lineTo(x2 - ux * s - uy * 3.4, y2 - uy * s + ux * 3.4)
    .closePath()
    .fill({ color, alpha });
}

function arrowOnCurve(g: Graphics, c: QuadCurve, color: number, alpha: number): void {
  arrowHead(g, c.cx, c.cy, c.x2, c.y2, color, alpha);
}

function liftColor(color: number, amount = 1.25): number {
  const r = Math.min(255, Math.round(((color >> 16) & 255) * amount));
  const g = Math.min(255, Math.round(((color >> 8) & 255) * amount));
  const b = Math.min(255, Math.round((color & 255) * amount));
  return (r << 16) | (g << 8) | b;
}

function pickLink(color: number, alpha: number, boost = 1): { color: number; alpha: number } {
  if (boost <= 1.001) return { color, alpha };
  return { color: liftColor(color, boost), alpha: Math.min(1, alpha * boost) };
}

function frameEdgeSig(frame: GraphFrame): string {
  return `${frame.edges.length}:${frame.vias.length}:${frame.bundle.size}`;
}

function gradientStrokeFast(
  g: Graphics,
  c: QuadCurve,
  head: number,
  band: number,
  color: number,
  width: number,
): void {
  const steps = 12;
  const denom = band * band * 0.22;
  let prev = quadPoint(c, 0);
  let prevU = 0;
  for (let i = 1; i <= steps; i++) {
    const u = i / steps;
    const p = quadPoint(c, u);
    const mid = (prevU + u) * 0.5;
    const glow = Math.exp(-((mid - head) ** 2) / denom);
    if (glow > 0.07) {
      const bright = liftColor(color, 1 + 1.1 * glow);
      const alpha = 0.42 + 0.58 * glow;
      const w = width * (1 + 0.65 * glow);
      g.moveTo(prev.x, prev.y).lineTo(p.x, p.y).stroke({ width: w, color: bright, alpha });
    }
    prev = p;
    prevU = u;
  }
}

function selectionAccent(empty: boolean, frozen: boolean): number {
  return empty || frozen ? 0xe8fbff : 0xffe08a;
}

function distToQuad(px: number, py: number, c: QuadCurve): number {
  let best = Infinity;
  let prev = quadPoint(c, 0);
  for (let i = 1; i <= 24; i++) {
    const p = quadPoint(c, i / 24);
    best = Math.min(best, distToSegment(px, py, prev.x, prev.y, p.x, p.y));
    prev = p;
  }
  return best;
}

interface LinkGradientFlow {
  key: string;
  color: number;
  width: number;
  band: number;
  t: number;
  speed: number;
}

export type RebuildOpts = {
  fit?: boolean;
  incremental?: boolean;
  seedId?: string;
};

export class GraphView {
  readonly world = new Container({ label: "world", eventMode: "static" });
  readonly camera: Camera;
  readonly fx = new GraphFx();
  frame: GraphFrame | null = null;
  selectedId = "";

  private readonly context = new Container({ label: "context" });
  private readonly path = new Container({ label: "path" });
  private readonly frozen = new Container({ label: "frozen" });
  private readonly front = new Container({ label: "front" });
  private readonly labels = new Container({ label: "labels", eventMode: "none" });
  private readonly edgesUnder = new Graphics({ label: "edges-under" });
  private readonly edgesGlow = new Graphics({ label: "edges-glow" });
  private readonly nodeCovers = new Graphics({ label: "node-covers" });
  private readonly edgeFlowDraw = new Graphics({ label: "edge-flow" });
  private readonly _nodeGlobal = new Point();
  private readonly _nodeLocal = new Point();
  private curvesDirty = true;
  private edgeFrameSig = "";
  private linkGradients: LinkGradientFlow[] = [];
  private readonly sprites = new Map<string, NodeSprite>();
  private dragging: { id: string; dx: number; dy: number } | null = null;
  private pendingDrag: { id: string; dx: number; dy: number } | null = null;
  private panning = false;
  private moved = 0;
  private lastPan = { x: 0, y: 0 };
  private ignoreViaClick = false;
  private lastTapAt = 0;
  private lastTapId = "";
  private lastShockAt = 0;
  private pressId = "";
  private pressGlobal = { x: 0, y: 0 };
  private dragged = false;
  private curves = new Map<string, QuadCurve>();
  private curveMeta = new Map<string, CurveMeta>();
  private suppressDblFocus = false;
  private selectedLink = "";
  private linkFlashNodeId = "";
  private linkFlashAge = 0;
  private linkFlashTimer = 0;
  private pinching = false;
  private pinchGesture = false;
  private pinchStartDist = 0;
  private pinchStartScale = 1;
  private readonly pointers = new Map<number, { x: number; y: number }>();
  private tipEl: HTMLElement | null = null;

  constructor(
    readonly app: Application,
    readonly model: GraphModel,
    readonly hooks: GraphViewHooks,
  ) {
    this.camera = new Camera(this.world);
    this.edgesUnder.eventMode = "none";
    this.edgesGlow.eventMode = "none";
    this.nodeCovers.eventMode = "none";
    this.edgeFlowDraw.eventMode = "none";
    this.world.addChild(this.edgesUnder, this.edgesGlow, this.nodeCovers, this.context, this.path, this.frozen, this.front, this.labels, this.edgeFlowDraw);
    this.world.sortableChildren = false;
    this.stackWorldLayers();
    this.app.stage.addChild(this.world);
    const overlay = new Container({ label: "fx-overlay", eventMode: "none" });
    overlay.zIndex = 20000;
    this.app.stage.sortableChildren = true;
    this.app.stage.addChild(overlay);
    this.world.hitArea = new Rectangle(-20000, -20000, 40000, 40000);
    this.fx.attach(this.world, this.context, this.path);
    this.fx.setOverlay(overlay);
    this.bindStage();
    this.bindPinch();
    this.app.ticker.add((ticker) => {
      this.camera.tick(ticker.deltaTime);
      this.fx.tick(ticker.deltaMS);
      if (this.linkFlashNodeId || this.linkGradients.length) this.tickLinkEffects(ticker.deltaMS);
      this.tickLayoutMotion(ticker.deltaMS);
      this.flushPendingLayoutTween();
      this.syncTickerIdle();
    });
  }

  /** Фиксированный порядок слоёв: рёбра → заливки узлов → обводки узлов → подписи. */
  private stackWorldLayers(): void {
    for (const layer of [
      this.edgesUnder,
      this.edgesGlow,
      this.nodeCovers,
      this.context,
      this.path,
      this.frozen,
      this.front,
      this.labels,
      this.edgeFlowDraw,
    ]) {
      this.world.addChild(layer);
    }
  }

  /** Пересчёт геометрии рёбер (кривые) — только при движении узлов. */
  markGeometryDirty(): void {
    this.curvesDirty = true;
  }

  /** Запускает цикл отрисовки, если он на паузе. */
  wake(): void {
    if (!this.app.ticker.started) this.app.ticker.start();
  }

  /** Один кадр без запуска ticker — для панорамы/зума в покое. */
  requestRender(): void {
    this.app.renderer.render(this.app.stage);
  }

  isTickerIdle(): boolean {
    return !this.app.ticker.started;
  }

  clearSelection(): void {
    this.selectedId = "";
    this.selectedLink = "";
    this.clearLinkFlash();
    this.clearFlows();
    for (const s of this.sprites.values()) {
      this.paintNode(
        s.body,
        s.radius,
        hexToNumber(nodeColor(s.node)),
        isEmptyObject(s.node),
        s.node.cooling === "FROZEN",
        false,
        false,
      );
      this.styleSelection(s, false);
      this.placeSprite(s);
    }
    this.refreshNodeCovers();
    if (this.frame) this.drawEdges(this.frame);
    this.requestRender();
  }

  private needsAnimation(): boolean {
    return this.camera.smoothing
      || this.fx.busy
      || this.layoutTweenActive
      || !!this.linkFlashNodeId
      || this.linkGradients.length > 0
      || this.panning
      || !!this.dragging
      || !!this.pendingDrag
      || this.pinching;
  }

  private syncTickerIdle(): void {
    if (!this.needsAnimation() && this.app.ticker.started) {
      this.app.ticker.stop();
      this.requestRender();
    }
  }

  private tickLinkEffects(deltaMS: number): void {
    let dirty = false;
    if (this.linkFlashNodeId) {
      this.linkFlashAge += deltaMS / 1000;
      if (this.linkFlashAge >= GraphView.LINK_FLASH_SEC) {
        this.linkFlashNodeId = "";
        this.linkFlashAge = 0;
      }
      dirty = true;
    }
    if (this.linkGradients.length) {
      const step = deltaMS / 1000;
      const keep: LinkGradientFlow[] = [];
      for (const flow of this.linkGradients) {
        flow.t += flow.speed * step;
        if (flow.t <= 1 + flow.band) keep.push(flow);
      }
      this.linkGradients = keep;
      dirty = true;
    }
    if (dirty) this.drawLinkEffects();
  }

  private startLinkFlash(nodeId: string): void {
    this.wake();
    window.clearTimeout(this.linkFlashTimer);
    this.linkFlashTimer = window.setTimeout(() => {
      this.linkFlashTimer = 0;
      this.linkFlashNodeId = nodeId;
      this.linkFlashAge = 0;
      this.drawLinkEffects();
    }, 320);
  }

  private clearLinkFlash(): void {
    window.clearTimeout(this.linkFlashTimer);
    this.linkFlashTimer = 0;
    if (!this.linkFlashNodeId) return;
    this.linkFlashNodeId = "";
    this.linkFlashAge = 0;
    this.drawLinkEffects();
  }

  /** Рёбра + камера за кадр: плавно к заранее вычисленному итоговому layout. */
  private tickLayoutMotion(deltaMS: number): void {
    if (!this.layoutTweenActive) return;
    this.layoutTweenAge += deltaMS / 1000;
    const t = Math.min(1, this.layoutTweenAge / GraphView.LAYOUT_MOVE_SEC);
    const movesDone = this.layoutMovePending <= 0;
    if (this.layoutMovePending > 0 && this.layoutMoveFrame) {
      this.refreshNodeCovers();
      this.maybeDrawEdges(this.layoutMoveFrame, 32, true);
    } else if (movesDone && this.layoutMoveFit) {
      this.refreshNodeCovers();
    }
    if (this.layoutMoveFit && this.layoutBoundsTo) {
      if (this.layoutCameraFrom) {
        this.lerpCameraToFit(this.layoutBoundsTo, t);
      } else if (this.layoutBoundsFrom) {
        this.fitFillLerpBounds(this.layoutBoundsFrom, this.layoutBoundsTo, t);
      }
    }
    const cameraDone = !this.layoutMoveFit || t >= 1 || !this.layoutBoundsTo;
    if (movesDone && cameraDone) this.finishLayoutTween();
  }

  private maybeDrawEdges(frame: GraphFrame, minIntervalMs = 0, skipEffects = false): void {
    if (minIntervalMs > 0) {
      const now = performance.now();
      if (now - this.edgeRedrawAt < minIntervalMs) return;
      this.edgeRedrawAt = now;
    }
    this.drawEdges(frame, { skipEffects });
  }

  private ensureCurves(frame: GraphFrame): void {
    const sig = frameEdgeSig(frame);
    const liveMotion =
      !!this.dragging
      || (this.layoutTweenActive && this.layoutMovePending > 0);
    if (liveMotion && this.curveMeta.size && this.edgeFrameSig === sig) {
      this.refreshCurvePositions();
      return;
    }
    if (liveMotion || this.curvesDirty || !this.curves.size || this.edgeFrameSig !== sig) {
      this.rebuildCurves(frame);
      if (!liveMotion) {
        this.curvesDirty = false;
        this.edgeFrameSig = sig;
      }
    }
  }

  private refreshCurvePositions(): void {
    for (const [key, meta] of this.curveMeta) {
      const a = this.sprites.get(meta.source);
      const b = this.sprites.get(meta.target);
      if (!a || !b) continue;
      this.curves.set(key, this.makeCurve(a, b, meta.offset));
    }
  }

  private lastFilters: UiFilters | null = null;
  private viaTimer = 0;
  private layoutMoveFrame: GraphFrame | null = null;
  private layoutMovePending = 0;
  private layoutMoveFit = false;
  private layoutViaPending = false;
  private layoutTweenActive = false;
  private layoutTweenAge = 0;
  private layoutBoundsFrom: Rectangle | null = null;
  private layoutBoundsTo: Rectangle | null = null;
  private layoutCameraFrom: { x: number; y: number; scale: number } | null = null;
  private edgeRedrawAt = 0;
  private incrementalRaf = 0;
  private incrementalDoneResolve: (() => void) | null = null;
  private pendingIncrementalContinue: {
    frame: GraphFrame;
    toAdd: string[];
    nextVisible: Set<string>;
    anchor: { x: number; y: number };
    seedId: string;
    targets?: Map<string, { x: number; y: number }>;
    boundsFrom?: Rectangle | null;
  } | null = null;
  private pendingLayoutTween: {
    targets: Map<string, { x: number; y: number }>;
    frame: GraphFrame;
    fitAfter: boolean;
  } | null = null;
  private incrementalAwaitingLayout = false;

  /** Ждёт завершения drill-down (исчезновение → тот же layout, что у кнопки Layout). */
  whenIncrementalReady(): Promise<void> {
    if (
      !this.pendingIncrementalContinue
      && !this.incrementalRaf
      && !this.incrementalAwaitingLayout
    ) {
      return Promise.resolve();
    }
    return new Promise((resolve) => {
      this.incrementalDoneResolve = resolve;
    });
  }

  private resolveIncrementalReady(): void {
    if (this.incrementalDoneResolve) {
      this.incrementalDoneResolve();
      this.incrementalDoneResolve = null;
    }
  }

  private static readonly LAYOUT_MOVE_SEC = 0.85;
  private static readonly LINK_FLASH_SEC = 0.82;

  rebuild(filters: UiFilters, fitOrOpts: boolean | RebuildOpts = true): GraphFrame {
    const opts: RebuildOpts = typeof fitOrOpts === "boolean" ? { fit: fitOrOpts } : fitOrOpts;
    if (opts.incremental && opts.seedId && this.sprites.size > 0) {
      return this.rebuildIncremental(filters, opts.seedId);
    }
    return this.rebuildFull(filters, opts.fit !== false);
  }

  private rebuildFull(filters: UiFilters, fit = true): GraphFrame {
    this.wake();
    this.markGeometryDirty();
    this.clearLinkFlash();
    this.lastFilters = filters;
    const frame = this.model.rebuild(filters);
    this.frame = frame;
    const nodes = [...frame.visible].map((id) => this.model.nodeById[id]).filter(Boolean);
    const links = [
      ...frame.edges.map((e) => ({ source: e.source, target: e.target })),
      ...frame.vias.map((e) => ({ source: e.source, target: e.target })),
    ];
    const pos = layoutNodes(nodes, links, { fresh: frame.bundle.size > 0 });
    this.stopLayoutTween();
    this.fx.clearNodeAnimations();
    this.clearFlows();
    for (const sprite of this.sprites.values()) {
      sprite.label.destroy();
      sprite.root.destroy({ children: true });
    }
    this.sprites.clear();
    this.labels.removeChildren();

    for (const n of nodes) {
      const p = pos.get(n.id) || { x: 0, y: 0 };
      const sprite = this.makeNode(n, p.x, p.y, frame.focus.has(n.id));
      this.sprites.set(n.id, sprite);
      this.placeSprite(sprite);
    }
    this.drawEdges(frame);
    this.rebuildFlows(frame);
    if (frame.viaPending) {
      window.clearTimeout(this.viaTimer);
      this.viaTimer = window.setTimeout(() => this.fillPendingVias(), 20);
    }
    this.fx.stopShock();
    this.world.filters = [];
    this.context.filters = [];
    this.path.filters = [];
    this.fx.clearContentFilters();
    this.fx.setFocusMode(frame.bundle.size > 0, this.path);
    this.stackWorldLayers();
    if (this.selectedId && this.sprites.has(this.selectedId)) this.selectNode(this.selectedId);
    if (fit) this.fit(true);
    this.syncTickerIdle();
    if (this.isTickerIdle()) this.requestRender();
    return frame;
  }

  private rebuildIncremental(filters: UiFilters, seedId: string): GraphFrame {
    this.wake();
    this.markGeometryDirty();
    this.clearLinkFlash();
    this.pendingLayoutTween = null;
    this.pendingIncrementalContinue = null;
    this.incrementalAwaitingLayout = false;
    if (this.incrementalRaf) {
      cancelAnimationFrame(this.incrementalRaf);
      this.incrementalRaf = 0;
    }
    const prevVisible = new Set(this.sprites.keys());
    this.lastFilters = filters;
    const frame = this.model.rebuild(filters);
    this.frame = frame;
    if (!frame.visible.has(seedId)) {
      return this.rebuildFull(filters, true);
    }

    const nextVisible = frame.visible;
    const toRemove = [...prevVisible].filter((id) => !nextVisible.has(id));
    const toAdd = [...nextVisible].filter((id) => !prevVisible.has(id));

    for (const id of toRemove) {
      const sprite = this.sprites.get(id);
      if (!sprite) continue;
      this.sprites.delete(id);
      if (this.selectedId === id) this.selectedId = "";
      this.fx.startNodeExit(sprite.root, sprite.label);
    }

    const seed = this.sprites.get(seedId);
    const anchor = seed
      ? { x: seed.root.x, y: seed.root.y }
      : { x: 0, y: 0 };

    this.clearFlows();
    this.fx.setFocusMode(frame.bundle.size > 0, this.path);
    this.stackWorldLayers();
    requestAnimationFrame(() => this.hooks.onFrame?.(frame));
    this.wake();
    this.requestRender();

    this.pendingIncrementalContinue = { frame, toAdd, nextVisible, anchor, seedId };
    if (!this.fx.hasExits) this.scheduleIncrementalContinue();
    return frame;
  }

  private scheduleIncrementalContinue(): void {
    if (this.incrementalRaf) cancelAnimationFrame(this.incrementalRaf);
    this.incrementalRaf = requestAnimationFrame(() => {
      this.incrementalRaf = 0;
      const payload = this.pendingIncrementalContinue;
      if (!payload) return;
      this.pendingIncrementalContinue = null;
      this.continueIncrementalAddNodes(payload);
    });
  }

  private continueIncrementalAddNodes(payload: {
    frame: GraphFrame;
    toAdd: string[];
    nextVisible: Set<string>;
    anchor: { x: number; y: number };
    seedId: string;
    targets?: Map<string, { x: number; y: number }>;
    boundsFrom?: Rectangle | null;
  }, offset = 0): void {
    const { frame, toAdd, nextVisible, anchor } = payload;
    if (!payload.boundsFrom) {
      payload.boundsFrom = this.spriteBounds();
    }
    if (!payload.targets) {
      const nodes = [...nextVisible].map((id) => this.model.nodeById[id]).filter(Boolean);
      const links = [
        ...frame.edges.map((e) => ({ source: e.source, target: e.target })),
        ...frame.vias.map((e) => ({ source: e.source, target: e.target })),
      ];
      payload.targets = layoutNodes(nodes, links, { fresh: frame.bundle.size > 0 });
    }
    const targets = payload.targets;
    const CHUNK = 14;
    const newNodes = toAdd.map((id) => this.model.nodeById[id]).filter(Boolean);
    const batch = newNodes.slice(offset, offset + CHUNK);

    for (const n of batch) {
      const p = targets.get(n.id) || anchor;
      const sprite = this.makeNode(n, p.x, p.y, frame.focus.has(n.id));
      this.sprites.set(n.id, sprite);
      this.placeSprite(sprite);
      rememberPosition(n.id, p.x, p.y);
      this.fx.startNodeEnter(sprite.root, sprite.label);
    }

    if (offset + CHUNK < newNodes.length) {
      this.incrementalRaf = requestAnimationFrame(() => {
        this.incrementalRaf = 0;
        this.continueIncrementalAddNodes(payload, offset + CHUNK);
      });
      return;
    }

    this.refreshNodeCovers();
    this.stackWorldLayers();
    this.wake();
    this.requestRender();
    this.incrementalRaf = requestAnimationFrame(() => {
      this.incrementalRaf = 0;
      this.continueIncrementalDraw(frame, targets, payload.boundsFrom ?? null, new Set(toAdd));
    });
  }

  private continueIncrementalDraw(
    frame: GraphFrame,
    targets: Map<string, { x: number; y: number }>,
    boundsFrom: Rectangle | null,
    skipMoveIds: Set<string>,
  ): void {
    this.markGeometryDirty();
    this.drawEdges(frame);
    this.rebuildFlows(frame);
    if (frame.viaPending) this.layoutViaPending = true;
    this.refreshNodeCovers();
    this.stackWorldLayers();
    this.wake();
    this.requestRender();
    this.incrementalAwaitingLayout = true;
    this.startLayoutTween(targets, frame, true, boundsFrom, skipMoveIds);
  }

  private flushPendingLayoutTween(): void {
    if (this.pendingIncrementalContinue && !this.fx.hasExits) {
      this.scheduleIncrementalContinue();
    }
    if (this.pendingLayoutTween && !this.fx.hasExits) {
      const pending = this.pendingLayoutTween;
      this.pendingLayoutTween = null;
      this.startLayoutTween(pending.targets, pending.frame, pending.fitAfter);
    }
  }

  fillPendingVias(): void {
    if (!this.frame || !this.lastFilters || !this.frame.viaPending) return;
    this.frame.vias = this.model.computeVias(this.frame.visible, this.lastFilters);
    this.frame.viaPending = false;
    this.markGeometryDirty();
    this.drawEdges(this.frame);
    this.rebuildFlows(this.frame);
    this.hooks.onFrame?.(this.frame);
    this.wake();
    this.syncTickerIdle();
    if (this.isTickerIdle()) this.requestRender();
  }

  private fitFillBounds(bounds: Rectangle, instant = true, fill = 0.8): void {
    this.camera.fitFill(bounds, this.app.screen, fill, this.graphTopInset());
    if (instant) this.camera.jumpToTarget();
  }

  private spriteBounds(): Rectangle | null {
    if (!this.sprites.size) return null;
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    for (const s of this.sprites.values()) {
      const labelW = s.label ? s.label.width + 12 : 0;
      const labelH = s.label ? s.label.height + 4 : 0;
      minX = Math.min(minX, s.root.x - s.radius);
      minY = Math.min(minY, s.root.y - s.radius - labelH * 0.5);
      maxX = Math.max(maxX, s.root.x + s.radius + labelW);
      maxY = Math.max(maxY, s.root.y + s.radius + labelH * 0.5);
    }
    return new Rectangle(minX, minY, maxX - minX, maxY - minY);
  }

  fit(instant = true, padding = 72, maxScale?: number): void {
    const bounds = this.spriteBounds();
    if (!bounds) return;
    this.wake();
    this.camera.fit(bounds, this.app.screen, padding, maxScale);
    if (instant) this.camera.jumpToTarget();
    this.syncTickerIdle();
    if (this.isTickerIdle()) this.requestRender();
  }

  fitFill(instant = true, fill = 0.8): void {
    const bounds = this.spriteBounds();
    if (!bounds) return;
    this.wake();
    this.fitFillBounds(bounds, instant, fill);
    this.syncTickerIdle();
    if (this.isTickerIdle()) this.requestRender();
  }

  private stopLayoutTween(): void {
    this.layoutMoveFrame = null;
    this.layoutMovePending = 0;
    this.layoutMoveFit = false;
    this.layoutViaPending = false;
    this.layoutTweenActive = false;
    this.layoutTweenAge = 0;
    this.layoutBoundsFrom = null;
    this.layoutBoundsTo = null;
    this.layoutCameraFrom = null;
    this.pendingLayoutTween = null;
  }

  private graphTopInset(): number {
    const wrap = document.getElementById("graphWrap");
    return wrap
      ? Number.parseFloat(getComputedStyle(wrap).getPropertyValue("--graph-header")) || 44
      : 44;
  }

  private fitFillLerpBounds(from: Rectangle, to: Rectangle, t: number): void {
    this.camera.fitFillLerp(from, to, this.app.screen, 0.92, this.graphTopInset(), t);
  }

  /** Drill-down: камера от текущего кадра к fit итогового layout (без скачка в t=0). */
  private lerpCameraToFit(boundsTo: Rectangle, t: number): void {
    const target = this.camera.computeFitFill(boundsTo, this.app.screen, 0.92, this.graphTopInset());
    const from = this.layoutCameraFrom;
    if (!target || !from) return;
    const e = t < 0.5 ? 4 * t * t * t : 1 - (-2 * t + 2) ** 3 / 2;
    this.camera.x = from.x + (target.x - from.x) * e;
    this.camera.y = from.y + (target.y - from.y) * e;
    this.camera.scale = from.scale + (target.scale - from.scale) * e;
    this.camera.targetX = this.camera.x;
    this.camera.targetY = this.camera.y;
    this.camera.targetScale = this.camera.scale;
    this.camera.smoothing = false;
    this.camera.apply();
  }

  private boundsFromTargets(targets: Map<string, { x: number; y: number }>): Rectangle | null {
    if (!targets.size) return null;
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    for (const [id, p] of targets) {
      const sprite = this.sprites.get(id);
      if (!sprite) continue;
      const labelW = sprite.label ? sprite.label.width + 12 : 0;
      const labelH = sprite.label ? sprite.label.height + 4 : 0;
      minX = Math.min(minX, p.x - sprite.radius);
      minY = Math.min(minY, p.y - sprite.radius - labelH * 0.5);
      maxX = Math.max(maxX, p.x + sprite.radius + labelW);
      maxY = Math.max(maxY, p.y + sprite.radius + labelH * 0.5);
    }
    if (!Number.isFinite(minX)) return null;
    return new Rectangle(minX, minY, maxX - minX, maxY - minY);
  }

  private startLayoutTween(
    targets: Map<string, { x: number; y: number }>,
    frame: GraphFrame,
    fitAfter = true,
    boundsFrom: Rectangle | null = null,
    skipMoveIds?: Set<string>,
  ): void {
    this.fx.clearNodeMoves();
    this.layoutMoveFrame = frame;
    this.layoutMoveFit = fitAfter;
    this.layoutMovePending = 0;
    this.layoutTweenAge = 0;
    this.layoutTweenActive = true;
    this.layoutBoundsTo = this.boundsFromTargets(targets);
    if (boundsFrom) {
      this.layoutCameraFrom = { x: this.camera.x, y: this.camera.y, scale: this.camera.scale };
      this.layoutBoundsFrom = boundsFrom;
    } else {
      this.layoutCameraFrom = null;
      this.layoutBoundsFrom = this.spriteBounds();
      if (fitAfter && this.layoutBoundsFrom && this.layoutBoundsTo) {
        this.fitFillLerpBounds(this.layoutBoundsFrom, this.layoutBoundsTo, 0);
      }
    }

    const launch = () => {
      for (const [id, target] of targets) {
        const sprite = this.sprites.get(id);
        if (!sprite) continue;
        this.placeSprite(sprite);
        if (skipMoveIds?.has(id)) continue;
        const dx = sprite.root.x - target.x;
        const dy = sprite.root.y - target.y;
        if (Math.hypot(dx, dy) < 1) {
          sprite.root.x = target.x;
          sprite.root.y = target.y;
          rememberPosition(id, target.x, target.y);
          this.placeSprite(sprite);
          continue;
        }
        this.layoutMovePending += 1;
        this.fx.startNodeMove(
          sprite.root,
          sprite.label,
          target.x,
          target.y,
          GraphView.LAYOUT_MOVE_SEC,
          () => {
            rememberPosition(id, sprite.root.x, sprite.root.y);
            this.placeSprite(sprite);
          },
          () => {
            this.layoutMovePending -= 1;
          },
        );
      }
      this.markGeometryDirty();
      if (this.layoutMoveFrame) this.drawEdges(this.layoutMoveFrame, { skipEffects: true });
      if (this.layoutMovePending <= 0 && !fitAfter) this.finishLayoutTween();
      else if (this.layoutMovePending <= 0 && fitAfter && !this.layoutBoundsFrom) {
        this.finishLayoutTween();
      }
    };

    requestAnimationFrame(() => launch());
  }

  private finishLayoutTween(): void {
    if (!this.layoutTweenActive) return;
    const frame = this.layoutMoveFrame;
    const vias = this.layoutViaPending;
    const incrementalDone = this.incrementalAwaitingLayout;
    if (this.layoutMoveFit && this.layoutBoundsTo) {
      if (this.layoutCameraFrom) {
        this.lerpCameraToFit(this.layoutBoundsTo, 1);
      } else if (this.layoutBoundsFrom) {
        this.fitFillLerpBounds(this.layoutBoundsFrom, this.layoutBoundsTo, 1);
      }
    }
    if (frame) {
      this.markGeometryDirty();
      this.drawEdges(frame);
    }
    this.stopLayoutTween();
    if (incrementalDone) {
      this.incrementalAwaitingLayout = false;
      this.resolveIncrementalReady();
    }
    this.syncTickerIdle();
    if (this.isTickerIdle()) this.requestRender();
    if (vias) {
      window.clearTimeout(this.viaTimer);
      this.viaTimer = window.setTimeout(() => this.fillPendingVias(), 20);
    }
  }

  relayout(filters: UiFilters): void {
    this.rebuild(filters, true);
  }

  private makeNode(n: GraphNode, x: number, y: number, focused: boolean): NodeSprite {
    const radius = nodeSize(n) / 2;
    const color = hexToNumber(nodeColor(n));
    const empty = isEmptyObject(n);
    const frozen = n.cooling === "FROZEN";
    const root = new Container({ x, y, eventMode: "static", cursor: "pointer" });
    root.hitArea = new Circle(0, 0, radius + 4);
    const body = new Graphics();
    this.paintNode(body, radius, color, empty, frozen, focused, n.id === this.selectedId);
    root.addChild(body);
    const label = new Text({
      text: String(n.label || n.name),
      style: {
        fontFamily: "Segoe UI, Tahoma, sans-serif",
        fontSize: 13,
        fontWeight: "400",
        fill: 0xf3efe6,
        letterSpacing: 0.2,
      },
    });
    label.anchor.set(0, 0.5);
    label.roundPixels = false;
    label.eventMode = "static";
    label.cursor = "pointer";
    this.labels.addChild(label);
    root.alpha = 1;
    root.on("pointerdown", (ev) => this.onNodeDown(n.id, ev));
    root.on("pointertap", (ev) => this.onNodeTap(n.id, ev));
    label.on("pointerdown", (ev) => this.onNodeDown(n.id, ev));
    label.on("pointertap", (ev) => this.onNodeTap(n.id, ev));
    const sprite: NodeSprite = { id: n.id, node: n, root, body, radius, label };
    this.placeLabel(sprite);
    return sprite;
  }

  private paintNode(
    g: Graphics,
    radius: number,
    _color: number,
    empty: boolean,
    frozen: boolean,
    focused: boolean,
    selected: boolean,
  ): void {
    g.clear();
    const ring = empty || frozen;
    const accent = selectionAccent(empty, frozen);
    let border = ring ? 0x7dd3f0 : 0x2a2622;
    if (selected) border = liftColor(accent, 1.45);
    else if (focused) border = ring ? 0xb8eef8 : 0xe0a050;
    const borderW = selected ? 2.5 : frozen ? 2 : 1;
    g.circle(0, 0, radius).stroke({ width: borderW, color: border });
    if (empty) g.circle(0, 0, radius * 0.5).stroke({ width: 1, color: 0x303030 });
  }

  private nodeFillColor(sprite: NodeSprite): number {
    const color = hexToNumber(nodeColor(sprite.node));
    return sprite.id === this.selectedId ? liftColor(color, 1.1) : color;
  }

  private styleSelection(sprite: NodeSprite, on: boolean): void {
    const accent = selectionAccent(isEmptyObject(sprite.node), sprite.node.cooling === "FROZEN");
    sprite.label.style.fill = on ? accent : 0xf3efe6;
    sprite.label.style.fontWeight = on ? "600" : "400";
  }

  private edgeKey(edge: GraphEdge, index: number): string {
    return `e:${edge.id || index}:${edge.source}:${edge.target}`;
  }

  private viaKey(via: ViaEdge, index: number): string {
    return `v:${index}:${via.source}:${via.target}`;
  }

  /** World-local XY — корректно при смене слоя (context/path/frozen/front). */
  private nodePos(sprite: NodeSprite): { x: number; y: number } {
    sprite.root.getGlobalPosition(this._nodeGlobal);
    this.world.toLocal(this._nodeGlobal, undefined, this._nodeLocal);
    return { x: this._nodeLocal.x, y: this._nodeLocal.y };
  }

  private makeCurve(from: NodeSprite, to: NodeSprite, offset: number): QuadCurve {
    const fp = this.nodePos(from);
    const tp = this.nodePos(to);
    const dx = tp.x - fp.x;
    const dy = tp.y - fp.y;
    const len = Math.hypot(dx, dy) || 1;
    const px = -dy / len;
    const py = dx / len;
    const cx = (fp.x + tp.x) / 2 + px * offset;
    const cy = (fp.y + tp.y) / 2 + py * offset;
    const toward = (ox: number, oy: number, r: number, tx: number, ty: number) => {
      const vx = tx - ox;
      const vy = ty - oy;
      const d = Math.hypot(vx, vy) || 1;
      return { x: ox + (vx / d) * r, y: oy + (vy / d) * r };
    };
    const s = toward(fp.x, fp.y, from.radius, cx, cy);
    const t = toward(tp.x, tp.y, to.radius, cx, cy);
    return { x1: s.x, y1: s.y, cx, cy, x2: t.x, y2: t.y };
  }

  private rebuildCurves(frame: GraphFrame): void {
    this.curves.clear();
    this.curveMeta.clear();
    type Item = { key: string; a: NodeSprite; b: NodeSprite };
    const groups = new Map<string, Item[]>();
    const push = (key: string, source: string, target: string) => {
      const a = this.sprites.get(source);
      const b = this.sprites.get(target);
      if (!a || !b) return;
      const gkey = source < target ? `${source}~${target}` : `${target}~${source}`;
      const list = groups.get(gkey) || [];
      list.push({ key, a, b });
      groups.set(gkey, list);
    };
    frame.edges.forEach((edge, i) => push(this.edgeKey(edge, i), edge.source, edge.target));
    frame.vias.forEach((via, i) => push(this.viaKey(via, i), via.source, via.target));
    for (const list of groups.values()) {
      const left = list[0].a.id < list[0].b.id ? list[0].a.id : list[0].b.id;
      const forward = list.filter((item) => item.a.id === left);
      const backward = list.filter((item) => item.a.id !== left);
      const pa = this.nodePos(list[0].a);
      const pb = this.nodePos(list[0].b);
      const span = Math.hypot(pb.x - pa.x, pb.y - pa.y) || 1;
      const bothWays = forward.length > 0 && backward.length > 0;
      const lane = Math.max(36, Math.min(72, span * 0.2));
      const step = Math.max(26, Math.min(74, span * 0.16));
      const place = (items: Item[], side: number) => {
        const n = items.length;
        items.forEach((item, i) => {
          const fan = n <= 1 ? 0 : (i - (n - 1) / 2) * step;
          let world = fan;
          if (bothWays) world = side * lane + fan;
          else if (n === 1) world = Math.min(58, Math.max(20, span * 0.15));
          const local = item.a.id === left ? world : -world;
          this.curveMeta.set(item.key, { source: item.a.id, target: item.b.id, offset: local });
          this.curves.set(item.key, this.makeCurve(item.a, item.b, local));
        });
      };
      if (bothWays) {
        place(forward, 1);
        place(backward, -1);
      } else {
        place(forward.length ? forward : backward, 1);
      }
    }
  }

  private layerFor(sprite: NodeSprite): Container {
    if (this.dragging?.id === sprite.id) return this.front;
    if (sprite.node.cooling === "FROZEN") return this.frozen;
    if (this.frame?.bundle.has(sprite.id) || this.frame?.focus.has(sprite.id) || sprite.id === this.selectedId) {
      return this.path;
    }
    return this.context;
  }

  private placeSprite(sprite: NodeSprite): void {
    const layer = this.layerFor(sprite);
    if (sprite.root.parent !== layer) layer.addChild(sprite.root);
    this.placeLabel(sprite);
  }

  private placeLabel(sprite: NodeSprite): void {
    sprite.label.position.set(sprite.root.x + sprite.radius + 6, sprite.root.y);
  }

  private linkHighlighted(key: string): boolean {
    return this.selectedLink === key;
  }

  private linkDrawStyle(rawColor: number, rawAlpha: number, key: string, baseWidth: number): {
    color: number;
    alpha: number;
    width: number;
  } {
    const selected = this.linkHighlighted(key);
    const boost = selected ? 1.25 : 1;
    const { color, alpha } = pickLink(rawColor, rawAlpha, boost);
    const width = selected ? 1.35 : baseWidth;
    return { color, alpha, width };
  }

  private linkFlashPulse(): number {
    if (!this.linkFlashNodeId) return 0;
    const t = Math.min(1, this.linkFlashAge / GraphView.LINK_FLASH_SEC);
    return (1 - t) ** 1.45;
  }

  private drawLinkFlashOverlay(g: Graphics, frame: GraphFrame, pulse: number): void {
    const nodeId = this.linkFlashNodeId;
    if (!nodeId || pulse <= 0.01) return;
    const alpha = 0.2 + 0.16 * pulse;
    const width = 1.02 + 0.18 * pulse;
    const boost = 1.12 + 0.13 * pulse;
    const touch = (source: string, target: string) => source === nodeId || target === nodeId;

    frame.edges.forEach((edge, i) => {
      if (!touch(edge.source, edge.target)) return;
      const a = this.sprites.get(edge.source);
      const b = this.sprites.get(edge.target);
      if (!a || !b) return;
      const curve = this.curves.get(this.edgeKey(edge, i));
      if (!curve) return;
      const never = this.model.isNeverLoadEdge(edge);
      const stale = !never && this.model.isStaleLoadEdge(edge);
      const intoArchive = this.isArchiveEdge(a, b);
      const rawColor = intoArchive
        ? hexToNumber(ARCHIVE_LINE)
        : never ? hexToNumber(NEVER_LINE) : stale ? hexToNumber(STALE_LINE) : 0x5c646c;
      const color = liftColor(rawColor, boost);
      strokeQuad(g, curve, color, Math.min(1, alpha), width);
    });

    frame.vias.forEach((via, i) => {
      if (!touch(via.source, via.target)) return;
      const a = this.sprites.get(via.source);
      const b = this.sprites.get(via.target);
      if (!a || !b) return;
      const curve = this.curves.get(this.viaKey(via, i));
      if (!curve) return;
      const never = this.model.isNeverDtpPath(via.path, via.source, via.target);
      const stale = !never && this.model.isStaleDtpPath(via.path, via.source, via.target);
      const intoArchive = this.isArchiveEdge(a, b);
      const rawColor = intoArchive
        ? hexToNumber(ARCHIVE_LINE)
        : never ? hexToNumber(NEVER_LINE) : stale ? hexToNumber(STALE_LINE) : 0x8a7349;
      const color = liftColor(rawColor, boost);
      strokeQuad(g, curve, color, Math.min(1, alpha * 0.96), width);
    });
  }

  private drawLinkEffects(): void {
    const g = this.edgesGlow;
    g.clear();
    const frame = this.frame;
    if (!frame) return;
    this.ensureCurves(frame);
    const pulse = this.linkFlashPulse();
    if (pulse > 0.01) this.drawLinkFlashOverlay(g, frame, pulse);
    for (const flow of this.linkGradients) {
      if (flow.t < 0) continue;
      const curve = this.curves.get(flow.key);
      if (!curve) continue;
      gradientStrokeFast(g, curve, flow.t, flow.band, flow.color, flow.width);
    }
  }

  private refreshNodeCovers(): void {
    const g = this.nodeCovers;
    g.clear();
    g.eventMode = "none";
    const pad = 0.5;
    for (const s of this.sprites.values()) {
      const p = this.nodePos(s);
      g.circle(p.x, p.y, s.radius + pad).fill({ color: this.nodeFillColor(s), alpha: 1 });
      if (isEmptyObject(s.node)) {
        g.circle(p.x, p.y, s.radius * 0.5).fill({ color: 0x000000, alpha: 1 });
      }
    }
  }

  private strokeSegment(
    g: Graphics,
    curve: QuadCurve,
    t0: number,
    t1: number,
    style: { color: number; alpha: number; width: number },
    dashed?: { dash: number; gap: number },
  ): void {
    const lo = Math.max(0, Math.min(t0, t1));
    const hi = Math.min(1, Math.max(t0, t1));
    if (hi - lo < 0.01) return;
    if (dashed) dashedQuadRange(g, curve, lo, hi, dashed.dash, dashed.gap, style.color, style.alpha, style.width);
    else if (lo <= 0.001 && hi >= 0.999) strokeQuad(g, curve, style.color, style.alpha, style.width);
    else strokeQuadRange(g, curve, lo, hi, style.color, style.alpha, style.width);
  }

  private strokeEdgeLayer(
    g: Graphics,
    curve: QuadCurve,
    style: { color: number; alpha: number; width: number },
    dashed?: { dash: number; gap: number },
  ): void {
    this.strokeSegment(g, curve, 0, 1, style, dashed);
  }

  private drawEdges(frame: GraphFrame, opts?: { skipEffects?: boolean }): void {
    this.ensureCurves(frame);
    this.edgesUnder.clear();
    this.edgesUnder.eventMode = "none";
    const under = this.edgesUnder;
    const highlight = frame.bundle.size > 0;
    frame.edges.forEach((edge, i) => {
      const a = this.sprites.get(edge.source);
      const b = this.sprites.get(edge.target);
      const curve = this.curves.get(this.edgeKey(edge, i));
      if (!a || !b || !curve) return;
      const hot = highlight && frame.bundle.has(edge.source) && frame.bundle.has(edge.target);
      const never = this.model.isNeverLoadEdge(edge);
      const stale = !never && this.model.isStaleLoadEdge(edge);
      const archiveSource = this.isArchiveNode(a.node);
      const archiveTarget = this.isArchiveNode(b.node);
      const rawColor = archiveSource || archiveTarget
        ? hexToNumber(ARCHIVE_LINE)
        : never ? hexToNumber(NEVER_LINE) : stale ? hexToNumber(STALE_LINE) : 0x5c646c;
      const rawAlpha = archiveSource || archiveTarget ? 0.88 : never || stale ? 0.75 : hot || !highlight ? 0.45 : 0.22;
      const key = this.edgeKey(edge, i);
      const style = this.linkDrawStyle(rawColor, rawAlpha, key, hot ? 1 : 0.8);
      this.strokeEdgeLayer(under, curve, style);
      arrowOnCurve(under, curve, style.color, style.alpha);
    });
    frame.vias.forEach((via, i) => {
      const a = this.sprites.get(via.source);
      const b = this.sprites.get(via.target);
      const curve = this.curves.get(this.viaKey(via, i));
      if (!a || !b || !curve) return;
      const never = this.model.isNeverDtpPath(via.path, via.source, via.target);
      const stale = !never && this.model.isStaleDtpPath(via.path, via.source, via.target);
      const archiveSource = this.isArchiveNode(a.node);
      const archiveTarget = this.isArchiveNode(b.node);
      const rawColor = archiveSource || archiveTarget
        ? hexToNumber(ARCHIVE_LINE)
        : never ? hexToNumber(NEVER_LINE) : stale ? hexToNumber(STALE_LINE) : 0x8a7349;
      const rawAlpha = archiveSource || archiveTarget ? 0.88 : never || stale ? 0.7 : 0.48;
      const key = this.viaKey(via, i);
      const style = this.linkDrawStyle(rawColor, rawAlpha, key, 1);
      const dashed = { dash: never || stale ? 3.5 : 4.5, gap: never || stale ? 3 : 2.5 };
      this.strokeEdgeLayer(under, curve, style, dashed);
      arrowOnCurve(under, curve, style.color, style.alpha);
    });
    if (!opts?.skipEffects && (this.linkFlashNodeId || this.linkGradients.length)) {
      this.drawLinkEffects();
    }
    this.refreshNodeCovers();
  }

  private clearFlows(): void {
    this.linkGradients = [];
    if (!this.linkFlashNodeId) this.edgesGlow.clear();
  }

  private rebuildFlows(_frame: GraphFrame): void {
    this.clearFlows();
  }

  private visibleEdgeColor(
    sourceId: string,
    targetId: string,
    never: boolean,
    stale: boolean,
    fallback: number,
  ): number {
    const source = this.sprites.get(sourceId);
    const target = this.sprites.get(targetId);
    if (this.isArchiveEdge(source, target)) return hexToNumber(ARCHIVE_LINE);
    if (never) return hexToNumber(NEVER_LINE);
    if (stale) return hexToNumber(STALE_LINE);
    return fallback;
  }

  private playLinkGradient(key: string, color: number, width = 1.25): void {
    if (!this.curves.has(key) && this.frame) this.ensureCurves(this.frame);
    this.clearFlows();
    this.linkGradients.push({
      key,
      color: liftColor(color, 1.15),
      width,
      band: 0.17,
      t: 0,
      speed: 1 / 0.36,
    });
    this.drawLinkEffects();
  }

  private playGradientsOnce(id: string, durationSec: number, kind: "small" | "full" = "full"): void {
    if (!this.frame) return;
    if (!this.curves.size && this.frame) this.ensureCurves(this.frame);
    const paths: { key: string; color: number; width: number }[] = [];
    this.frame.edges.forEach((edge, i) => {
      if (edge.source !== id) return;
      const key = this.edgeKey(edge, i);
      if (!this.curves.has(key)) return;
      const never = this.model.isNeverLoadEdge(edge);
      const stale = !never && this.model.isStaleLoadEdge(edge);
      paths.push({
        key,
        color: liftColor(this.visibleEdgeColor(edge.source, edge.target, never, stale, 0x5c646c), 1.12),
        width: kind === "small" ? 1.15 : 1.3,
      });
    });
    this.frame.vias.forEach((via, i) => {
      if (via.source !== id) return;
      const key = this.viaKey(via, i);
      if (!this.curves.has(key)) return;
      const never = this.model.isNeverDtpPath(via.path, via.source, via.target);
      const stale = !never && this.model.isStaleDtpPath(via.path, via.source, via.target);
      paths.push({
        key,
        color: liftColor(this.visibleEdgeColor(via.source, via.target, never, stale, 0x8a7349), 1.12),
        width: 1.25,
      });
    });
    if (!paths.length) return;
    const large = paths.length > 28;
    const capped = large ? paths.slice(0, kind === "full" ? 20 : 14) : paths;
    const speed = 1 / Math.max(durationSec * 0.78, 0.2);
    const band = kind === "small" ? 0.15 : 0.18;
    this.linkGradients = capped.map(({ key, color, width }, idx) => ({
      key,
      color,
      width,
      band,
      t: -(idx % 4) * 0.05,
      speed,
    }));
    this.drawLinkEffects();
  }

  private bindStage(): void {
    const stage = this.app.stage;
    stage.eventMode = "static";
    stage.hitArea = this.app.screen;
    this.app.canvas.addEventListener("wheel", (ev) => {
      ev.preventDefault();
      this.wake();
      const factor = ev.deltaY > 0 ? 0.9 : 1.11;
      const mapped = this.mapClient(ev.clientX, ev.clientY);
      this.camera.zoomAt(mapped.x, mapped.y, factor);
      this.requestRender();
      this.syncTickerIdle();
    }, { passive: false });

    this.world.on("pointerdown", (ev: FederatedPointerEvent) => {
      if (ev.target !== this.world || this.pinching || this.pointers.size >= 1) return;
      this.wake();
      this.panning = true;
      this.moved = 0;
      this.dragged = false;
      this.ignoreViaClick = false;
      this.lastPan = { x: ev.global.x, y: ev.global.y };
    });
    this.app.stage.on("globalpointermove", (ev: FederatedPointerEvent) => {
      if (this.pinching) return;
      if (this.pendingDrag && !this.dragging) {
        const screen = Math.hypot(ev.global.x - this.pressGlobal.x, ev.global.y - this.pressGlobal.y);
        if (screen > 8) {
          this.dragged = true;
          this.moved = screen;
          this.dragging = this.pendingDrag;
          this.pendingDrag = null;
          this.moveDragged(ev);
        }
        return;
      }
      if (this.dragging) {
        this.moveDragged(ev);
        return;
      }
      if (this.panning) {
        const dx = ev.global.x - this.lastPan.x;
        const dy = ev.global.y - this.lastPan.y;
        this.moved += Math.hypot(dx, dy);
        this.camera.pan(dx, dy);
        this.lastPan = { x: ev.global.x, y: ev.global.y };
        this.requestRender();
      }
    });
    const endDrag = () => {
      if (this.dragging) {
        const sprite = this.sprites.get(this.dragging.id);
        if (sprite) this.placeSprite(sprite);
      }
      if (!this.dragged) this.moved = 0;
      this.dragging = null;
      this.pendingDrag = null;
      this.panning = false;
      this.syncTickerIdle();
      if (this.isTickerIdle()) this.requestRender();
    };
    this.app.stage.on("pointerup", endDrag);
    this.app.stage.on("pointerupoutside", endDrag);
  }

  private bindPinch(): void {
    const canvas = this.app.canvas;
    canvas.style.touchAction = "none";

    const mapScreen = (clientX: number, clientY: number) => {
      const point = { x: 0, y: 0 };
      this.app.renderer.events.mapPositionToPoint(point, clientX, clientY);
      return point;
    };

    const pinchMid = () => {
      const pts = [...this.pointers.values()];
      if (pts.length < 2) return null;
      return { x: (pts[0].x + pts[1].x) / 2, y: (pts[0].y + pts[1].y) / 2 };
    };

    const onDown = (ev: PointerEvent) => {
      this.wake();
      this.pointers.set(ev.pointerId, { x: ev.clientX, y: ev.clientY });
      if (this.pointers.size === 2) {
        this.pinching = true;
        this.panning = false;
        this.pendingDrag = null;
        this.dragging = null;
        const pts = [...this.pointers.values()];
        this.pinchStartDist = Math.hypot(pts[1].x - pts[0].x, pts[1].y - pts[0].y) || 1;
        this.pinchStartScale = this.camera.scale;
      }
    };

    const onMove = (ev: PointerEvent) => {
      if (!this.pointers.has(ev.pointerId)) return;
      this.pointers.set(ev.pointerId, { x: ev.clientX, y: ev.clientY });
      if (this.pointers.size !== 2 || !this.pinching) return;
      const pts = [...this.pointers.values()];
      const dist = Math.hypot(pts[1].x - pts[0].x, pts[1].y - pts[0].y) || 1;
      if (Math.abs(dist - this.pinchStartDist) > 4) this.pinchGesture = true;
      const mid = pinchMid();
      if (!mid) return;
      const mapped = mapScreen(mid.x, mid.y);
      this.camera.setScaleAt(mapped.x, mapped.y, this.pinchStartScale * (dist / this.pinchStartDist));
      this.requestRender();
    };

    const onUp = (ev: PointerEvent) => {
      this.pointers.delete(ev.pointerId);
      if (this.pointers.size < 2) {
        this.pinching = false;
        this.pinchStartDist = 0;
        this.syncTickerIdle();
        if (this.isTickerIdle()) this.requestRender();
      }
    };

    canvas.addEventListener("pointerdown", onDown);
    canvas.addEventListener("pointermove", onMove);
    canvas.addEventListener("pointerup", onUp);
    canvas.addEventListener("pointercancel", onUp);
  }

  bindTooltip(el: HTMLElement): void {
    this.tipEl = el;
    const canvas = this.app.canvas;
    const refresh = (ev: PointerEvent) => {
      if (this.dragging || this.panning || this.pinching || this.pendingDrag) {
        this.hideTip();
        return;
      }
      const point = this.mapClient(ev.clientX, ev.clientY);
      const id = this.hitNodeBodyAt(point.x, point.y) || this.hitNodeLabelAt(point.x, point.y);
      if (!id) {
        this.hideTip();
        return;
      }
      const node = this.model.nodeById[id];
      const text = node ? (node.txtlg?.trim() || bwText(node, this.model.texts).trim()) : "";
      if (!text) {
        this.hideTip();
        return;
      }
      const sprite = this.sprites.get(id);
      const fill = sprite?.label.style.fill;
      const textColor = typeof fill === "number"
        ? `#${(fill & 0xffffff).toString(16).padStart(6, "0")}`
        : "#f3efe6";
      this.showTip(ev.clientX, ev.clientY, text, textColor);
    };
    canvas.addEventListener("pointermove", refresh);
    canvas.addEventListener("pointerleave", () => this.hideTip());
  }

  private showTip(clientX: number, clientY: number, text: string, textColor: string): void {
    if (!this.tipEl) return;
    this.tipEl.textContent = text;
    this.tipEl.style.color = textColor;
    this.tipEl.classList.add("on");
    const pad = 14;
    let x = clientX + pad;
    let y = clientY + pad;
    this.tipEl.style.left = `${x}px`;
    this.tipEl.style.top = `${y}px`;
    requestAnimationFrame(() => {
      if (!this.tipEl?.classList.contains("on")) return;
      const w = this.tipEl.offsetWidth;
      const h = this.tipEl.offsetHeight;
      x = Math.min(x, window.innerWidth - w - 8);
      y = Math.min(y, window.innerHeight - h - 8);
      this.tipEl.style.left = `${Math.max(8, x)}px`;
      this.tipEl.style.top = `${Math.max(8, y)}px`;
    });
  }

  private hideTip(): void {
    this.tipEl?.classList.remove("on");
  }

  private mapClient(clientX: number, clientY: number): { x: number; y: number } {
    const point = { x: 0, y: 0 };
    this.app.renderer.events.mapPositionToPoint(point, clientX, clientY);
    return point;
  }

  private pointerInParent(ev: FederatedPointerEvent, parent: Container): { x: number; y: number } {
    return parent.toLocal(ev.global);
  }

  private moveDragged(ev: FederatedPointerEvent): void {
    if (!this.dragging) return;
    const sprite = this.sprites.get(this.dragging.id);
    if (!sprite) return;
    const parent = sprite.root.parent ?? this.world;
    const local = this.pointerInParent(ev, parent);
    const nx = local.x + this.dragging.dx;
    const ny = local.y + this.dragging.dy;
    this.moved += Math.hypot(nx - sprite.root.x, ny - sprite.root.y);
    sprite.root.position.set(nx, ny);
    rememberPosition(sprite.id, sprite.root.x, sprite.root.y);
    this.placeLabel(sprite);
    if (this.frame) this.drawEdges(this.frame, { skipEffects: true });
  }

  private onNodeDown(id: string, ev: FederatedPointerEvent): void {
    ev.stopPropagation();
    this.wake();
    const sprite = this.sprites.get(id);
    if (!sprite) return;
    this.camera.smoothing = false;
    this.front.addChild(sprite.root);
    const local = this.pointerInParent(ev, sprite.root.parent ?? this.world);
    this.moved = 0;
    this.dragged = false;
    this.pressId = id;
    this.pressGlobal = { x: ev.global.x, y: ev.global.y };
    this.ignoreViaClick = true;
    this.pendingDrag = { id, dx: sprite.root.x - local.x, dy: sprite.root.y - local.y };
    this.dragging = null;
  }

  private onNodeTap(id: string, ev: FederatedPointerEvent): void {
    if (this.dragged || this.pinchGesture) {
      this.pinchGesture = false;
      return;
    }
    const sx = ev.global.x;
    const sy = ev.global.y;
    if (!this.hitNodeBodyAt(sx, sy)) {
      const link = this.hitLinkAt(sx, sy);
      if (link) {
        this.describeLink(link);
        return;
      }
    }
    const now = performance.now();
    const doubled = this.lastTapId === id && now - this.lastTapAt < 450;
    this.lastTapAt = now;
    this.lastTapId = id;
    if (doubled) {
      this.clearLinkFlash();
      this.suppressDblFocus = true;
      this.fx.stopShock();
      this.hooks.onNodeFocus(id);
      return;
    }
    this.selectNode(id, { flashLinks: true });
    this.hooks.onNodeSelect(id);
    this.playShock(id, "small");
  }

  lastTouchedNode(): string {
    return this.pressId || this.lastTapId;
  }

  consumeFocusHandled(): boolean {
    const handled = this.suppressDblFocus;
    this.suppressDblFocus = false;
    return handled;
  }

  selectNode(id: string, opts?: { flashLinks?: boolean }): void {
    const prev = this.selectedId;
    this.selectedId = id;
    this.lastTapId = id;
    this.ignoreViaClick = true;
    if (opts?.flashLinks) this.startLinkFlash(id);
    let edgesDirty = false;
    if (this.selectedLink) {
      this.selectedLink = "";
      edgesDirty = true;
    }
    const touch = new Set<string>([id]);
    if (prev && prev !== id) touch.add(prev);
    for (const sid of touch) {
      const s = this.sprites.get(sid);
      if (!s) continue;
      const isFocus = sid === id;
      this.paintNode(
        s.body,
        s.radius,
        hexToNumber(nodeColor(s.node)),
        isEmptyObject(s.node),
        s.node.cooling === "FROZEN",
        isFocus,
        isFocus,
      );
      this.styleSelection(s, isFocus);
      this.placeSprite(s);
    }
    const chosen = this.sprites.get(id);
    if (chosen) this.front.addChild(chosen.root);
    this.fx.setFocusMode(!!this.frame?.bundle.size, this.path);
    if (edgesDirty && this.frame) this.drawEdges(this.frame);
    else {
      this.refreshNodeCovers();
      this.requestRender();
    }
  }

  consumeViaGuard(): boolean {
    const skip = this.ignoreViaClick || this.moved > 6;
    this.ignoreViaClick = false;
    return skip;
  }

  didDrag(): boolean {
    const was = this.dragged;
    this.dragged = false;
    return was;
  }

  didPinch(): boolean {
    const was = this.pinchGesture;
    this.pinchGesture = false;
    return was;
  }

  private isArchiveNode(node: GraphNode | undefined): boolean {
    if (!node) return false;
    return node.cooling === "FROZEN" || isEmptyObject(node);
  }

  private isArchiveEdge(source: NodeSprite | undefined, target: NodeSprite | undefined): boolean {
    return this.isArchiveNode(source?.node) || this.isArchiveNode(target?.node);
  }

  playFocusFx(_id: string): number {
    // Drill-down: только выделение узла, без shockwave-кольца.
    return 0;
  }

  playShock(id: string, kind: "small" | "full", opts?: { gradients?: boolean }): number {
    try {
      this.wake();
      if (kind === "small" && performance.now() - this.lastShockAt < 120) return 0;
      const sprite = this.sprites.get(id);
      if (!sprite) return 0;
      this.lastShockAt = performance.now();
      const archived = isEmptyObject(sprite.node) || sprite.node.cooling === "FROZEN";
      const color = archived ? 0xe8fbff : 0xffe08a;
      const ms = this.fx.startShock(
        this.world,
        sprite.root.x,
        sprite.root.y,
        kind,
        sprite.radius,
        this.camera.scale,
        color,
      );
      if (opts?.gradients !== false) {
        this.playGradientsOnce(id, (ms || 700) / 1000, kind);
      }
      return ms;
    } catch (err) {
      console.error(err);
      return 0;
    }
  }

  hitNodeAt(sx: number, sy: number): string | null {
    return this.hitNodeBodyAt(sx, sy) || this.hitNodeLabelAt(sx, sy);
  }

  hitNodeBodyAt(sx: number, sy: number): string | null {
    const w = this.world.toLocal({ x: sx, y: sy });
    let best = "";
    let bestD = Infinity;
    const pad = 8 / this.camera.scale;
    for (const s of this.sprites.values()) {
      const d = Math.hypot(w.x - s.root.x, w.y - s.root.y);
      if (d <= s.radius + pad && d < bestD) {
        bestD = d;
        best = s.id;
      }
    }
    return best || null;
  }

  hitNodeLabelAt(sx: number, sy: number): string | null {
    const w = this.world.toLocal({ x: sx, y: sy });
    let best = "";
    let bestD = Infinity;
    for (const s of this.sprites.values()) {
      const lw = s.label.width;
      const lh = Math.max(s.label.height, 14);
      const lx = s.root.x + s.radius + 6;
      const ly = s.root.y - lh / 2;
      if (w.x < lx || w.x > lx + lw || w.y < ly || w.y > ly + lh) continue;
      const d = Math.hypot(w.x - s.root.x, w.y - s.root.y);
      if (d < bestD) {
        bestD = d;
        best = s.id;
      }
    }
    return best || null;
  }

  hitViaAt(sx: number, sy: number): ViaEdge | null {
    const hit = this.hitLinkAt(sx, sy);
    return hit?.kind === "via" ? hit.via : null;
  }

  hitLinkAt(sx: number, sy: number): { kind: "via"; via: ViaEdge } | { kind: "edge"; edge: GraphEdge } | null {
    if (!this.frame) return null;
    if (!this.curves.size && this.frame) this.ensureCurves(this.frame);
    const w = this.world.toLocal({ x: sx, y: sy });
    const maxD = 14 / Math.max(this.camera.scale, 0.08);
    let bestD = maxD;
    let best: { kind: "via"; via: ViaEdge } | { kind: "edge"; edge: GraphEdge } | null = null;
    const consider = (
      key: string,
      pick: { kind: "via"; via: ViaEdge } | { kind: "edge"; edge: GraphEdge },
    ) => {
      const curve = this.curves.get(key);
      if (!curve) return;
      const d = distToQuad(w.x, w.y, curve);
      if (d < bestD) {
        bestD = d;
        best = pick;
      }
    };
    this.frame.edges.forEach((edge, i) => consider(this.edgeKey(edge, i), { kind: "edge", edge }));
    this.frame.vias.forEach((via, i) => consider(this.viaKey(via, i), { kind: "via", via }));
    return best;
  }

  private keyForHit(hit: { kind: "via"; via: ViaEdge } | { kind: "edge"; edge: GraphEdge }): string {
    if (!this.frame) return "";
    if (hit.kind === "edge") {
      const index = this.frame.edges.indexOf(hit.edge);
      return index >= 0 ? this.edgeKey(hit.edge, index) : "";
    }
    const index = this.frame.vias.indexOf(hit.via);
    return index >= 0 ? this.viaKey(hit.via, index) : "";
  }

  describeLink(hit: { kind: "via"; via: ViaEdge } | { kind: "edge"; edge: GraphEdge }): void {
    this.selectedLink = this.keyForHit(hit);
    if (this.frame) this.drawEdges(this.frame);
    const curve = this.curves.get(this.selectedLink);
    if (curve) {
      const tint = hit.kind === "via"
        ? this.visibleEdgeColor(
          hit.via.source,
          hit.via.target,
          this.model.isNeverDtpPath(hit.via.path, hit.via.source, hit.via.target),
          this.model.isStaleDtpPath(hit.via.path, hit.via.source, hit.via.target),
          0x8a7349,
        )
        : this.visibleEdgeColor(
          hit.edge.source,
          hit.edge.target,
          this.model.isNeverLoadEdge(hit.edge),
          this.model.isStaleLoadEdge(hit.edge),
          0x5c646c,
        );
      this.playLinkGradient(this.selectedLink, liftColor(tint, 1.25));
    }
    if (hit.kind === "via") {
      this.describeVia(hit.via);
      return;
    }
    const edge = hit.edge;
    const src = this.model.nodeById[edge.source];
    const tgt = this.model.nodeById[edge.target];
    const never = this.model.isNeverLoadEdge(edge);
    const stale = !never && this.model.isStaleLoadEdge(edge);
    const lastOk = this.model.lastLiveOnDtpPath([edge.source, edge.target], edge.source, edge.target);
    const path = [src, tgt].filter(Boolean).map((node) => (
      node!.txtlg ? `${node!.name} (${node!.txtlg})` : node!.name
    )).join(" → ");
    this.hooks.onEdgeSelect("edge", {
      title: never ? "never — DTP ни разу не грузился" : (stale ? "stale — давно не грузился" : "Ребро"),
      lastOk,
      path: `${path}${edge.type ? ` · ${edge.type}` : ""}`,
      stale,
      never,
    });
  }

  describeVia(via: ViaEdge): void {
    const never = this.model.isNeverDtpPath(via.path, via.source, via.target);
    const stale = !never && this.model.isStaleDtpPath(via.path, via.source, via.target);
    const lastOk = this.model.lastLiveOnDtpPath(via.path, via.source, via.target);
    const path = via.path.map((id) => {
      const node = this.model.nodeById[id];
      if (!node) return id;
      return node.txtlg ? `${node.name} (${node.txtlg})` : node.name;
    }).join(" → ");
    this.hooks.onEdgeSelect("via", {
      title: never ? "never — DTP ни разу не грузился" : (stale ? "stale — давно не грузился" : "Связь через скрытые объекты"),
      lastOk,
      path,
      stale,
      never,
    });
  }
}

function distToSegment(px: number, py: number, x1: number, y1: number, x2: number, y2: number): number {
  const dx = x2 - x1;
  const dy = y2 - y1;
  const l2 = dx * dx + dy * dy || 1;
  const t = Math.max(0, Math.min(1, ((px - x1) * dx + (py - y1) * dy) / l2));
  return Math.hypot(px - (x1 + t * dx), py - (y1 + t * dy));
}

export function nodeDetailHtml(model: GraphModel, id: string): { html: string; edgesHtml: string; stale: boolean; never: boolean } {
  const n = model.nodeById[id];
  if (!n) return { html: "", edgesHtml: "", stale: false, never: false };
  const lines = [...model.outgoing(id), ...model.incoming(id)]
    .slice(0, 28)
    .map((edge) => {
      const other = model.nodeById[edge.source === id ? edge.target : edge.source];
      const line = `${edge.type || ""} ${edge.source === id ? "→" : "←"} ${model.neighborLabel(other)}`;
      if (model.isNeverLoadEdge(edge)) return `<span class="never-ink">${esc(line)}</span>`;
      return model.isStaleLoadEdge(edge) ? `<span class="stale-ink">${esc(line)}</span>` : esc(line);
    });
  const html =
    `<p><span class="obj-name">${esc(n.name)}</span><br/><span class="meta">${n.type} · ${displayPrefix(n.prefix) || "—"} · ${n.cooling || (model.isEmpty(n) ? "EMPTY" : "")}</span></p>` +
    (n.txtlg ? `<p class="obj-desc">${esc(n.txtlg)}</p>` : `<p class="meta">наименование BW не найдено</p>`) +
    (model.isEmpty(n) ? `<p class="meta">пустой объект — нет объёма данных</p>` : "") +
    (n.disk_gb != null ? `<p>${n.disk_gb} GB</p>` : "") +
    (n.last_ok || n.last_data ? `<p>последняя загрузка: ${fmtDate(n.last_ok)}<br/><span class="meta">данные до: ${fmtDate(n.last_data)}</span></p>` : "");
  const edgesHtml = lines.length
    ? `<p class="meta">${lines.join("<br/>")}</p>`
    : `<p class="meta">нет связей</p>`;
  return { html, edgesHtml, stale: false, never: false };
}
