import { Container, Rectangle } from "pixi.js";

export class Camera {
  x = 0;
  y = 0;
  scale = 1;
  targetX = 0;
  targetY = 0;
  targetScale = 1;
  smoothing = false;
  minScale = 0.05;
  maxScale = 4;

  constructor(readonly world: Container) {}

  apply(): void {
    this.world.position.set(this.x, this.y);
    this.world.scale.set(this.scale);
  }

  clampScale(value: number): number {
    return Math.min(this.maxScale, Math.max(this.minScale, value));
  }

  zoomAt(screenX: number, screenY: number, factor: number): void {
    const next = this.clampScale(this.scale * factor);
    const local = this.world.toLocal({ x: screenX, y: screenY });
    this.scale = next;
    this.x = screenX - local.x * this.scale;
    this.y = screenY - local.y * this.scale;
    this.targetX = this.x;
    this.targetY = this.y;
    this.targetScale = this.scale;
    this.smoothing = false;
    this.apply();
  }

  pan(dx: number, dy: number): void {
    this.x += dx;
    this.y += dy;
    this.targetX = this.x;
    this.targetY = this.y;
    this.smoothing = false;
    this.apply();
  }

  screenToWorld(sx: number, sy: number): { x: number; y: number } {
    return this.world.toLocal({ x: sx, y: sy });
  }

  focusOn(wx: number, wy: number, screen: { width: number; height: number }, scale = 1.35): void {
    this.targetScale = this.clampScale(scale);
    this.targetX = screen.width / 2 - wx * this.targetScale;
    this.targetY = screen.height / 2 - wy * this.targetScale;
    this.smoothing = true;
  }

  fit(bounds: Rectangle, screen: { width: number; height: number }, padding = 54, maxScale?: number): void {
    if (!bounds.width && !bounds.height) return;
    const w = Math.max(80, bounds.width);
    const h = Math.max(80, bounds.height);
    const sx = (screen.width - padding * 2) / w;
    const sy = (screen.height - padding * 2) / h;
    let targetScale = this.clampScale(Math.min(sx, sy));
    if (maxScale != null) targetScale = Math.min(targetScale, maxScale);
    const cx = bounds.x + bounds.width / 2;
    const cy = bounds.y + bounds.height / 2;
    this.targetScale = targetScale;
    this.targetX = screen.width / 2 - cx * targetScale;
    this.targetY = screen.height / 2 - cy * targetScale;
    this.smoothing = true;
  }

  fitFill(
    bounds: Rectangle,
    screen: { width: number; height: number },
    fill = 0.8,
    topInset = 0,
  ): void {
    const fit = this.computeFitFill(bounds, screen, fill, topInset);
    if (!fit) return;
    this.targetScale = fit.scale;
    this.targetX = fit.x;
    this.targetY = fit.y;
    this.smoothing = true;
  }

  /** Параметры камеры для fitFill без применения. */
  computeFitFill(
    bounds: Rectangle,
    screen: { width: number; height: number },
    fill = 0.8,
    topInset = 0,
  ): { x: number; y: number; scale: number } | null {
    if (!bounds.width && !bounds.height) return null;
    const w = Math.max(80, bounds.width);
    const h = Math.max(80, bounds.height);
    const viewW = screen.width;
    const viewH = Math.max(80, screen.height - topInset);
    const scale = this.clampScale(Math.min((viewW * fill) / w, (viewH * fill) / h));
    const cx = bounds.x + bounds.width / 2;
    const cy = bounds.y + bounds.height / 2;
    return {
      scale,
      x: viewW / 2 - cx * scale,
      y: topInset + viewH / 2 - cy * scale,
    };
  }

  /** Плавный переход камеры между двумя fit-состояниями (t ∈ [0,1], ease-in-out). */
  fitFillLerp(
    boundsA: Rectangle,
    boundsB: Rectangle,
    screen: { width: number; height: number },
    fill: number,
    topInset: number,
    t: number,
  ): void {
    const a = this.computeFitFill(boundsA, screen, fill, topInset);
    const b = this.computeFitFill(boundsB, screen, fill, topInset);
    if (!a || !b) return;
    const e = t < 0.5 ? 4 * t * t * t : 1 - (-2 * t + 2) ** 3 / 2;
    this.x = a.x + (b.x - a.x) * e;
    this.y = a.y + (b.y - a.y) * e;
    this.scale = a.scale + (b.scale - a.scale) * e;
    this.targetX = this.x;
    this.targetY = this.y;
    this.targetScale = this.scale;
    this.smoothing = false;
    this.apply();
  }

  setScaleAt(screenX: number, screenY: number, scale: number): void {
    const next = this.clampScale(scale);
    const local = this.world.toLocal({ x: screenX, y: screenY });
    this.scale = next;
    this.x = screenX - local.x * this.scale;
    this.y = screenY - local.y * this.scale;
    this.targetX = this.x;
    this.targetY = this.y;
    this.targetScale = this.scale;
    this.smoothing = false;
    this.apply();
  }

  jumpToTarget(): void {
    this.x = this.targetX;
    this.y = this.targetY;
    this.scale = this.targetScale;
    this.smoothing = false;
    this.apply();
  }

  tick(deltaTime: number): void {
    if (!this.smoothing) return;
    const t = 1 - Math.pow(0.86, deltaTime);
    this.x += (this.targetX - this.x) * t;
    this.y += (this.targetY - this.y) * t;
    this.scale += (this.targetScale - this.scale) * t;
    if (
      Math.abs(this.targetX - this.x) < 0.4 &&
      Math.abs(this.targetY - this.y) < 0.4 &&
      Math.abs(this.targetScale - this.scale) < 0.002
    ) {
      this.x = this.targetX;
      this.y = this.targetY;
      this.scale = this.targetScale;
      this.smoothing = false;
    }
    this.apply();
  }
}
