import canonicalUrl from "../../../toolkit/graph/canonical.json?url";
import textsUrl from "../../../toolkit/viewer/bw-texts.js?url";
import activityUrl from "../../../toolkit/viewer/dtp-activity.js?url";
import type { LineageGraph, Snapshots } from "../graph/types";

function runWindowScript(src: string): Record<string, unknown> {
  const win: Record<string, unknown> = {};
  const fn = new Function("window", src);
  fn(win);
  return win;
}

export async function loadSnapshots(): Promise<Snapshots> {
  const [graphRes, textsRes, activityRes] = await Promise.all([
    fetch(canonicalUrl),
    fetch(textsUrl),
    fetch(activityUrl),
  ]);
  if (!graphRes.ok) throw new Error(`не удалось прочитать снимок canonical.json (${graphRes.status})`);
  const graph = (await graphRes.json()) as LineageGraph;
  let textsWin: Record<string, unknown> = {};
  let actWin: Record<string, unknown> = {};
  try { textsWin = runWindowScript(await textsRes.text()); } catch { /* texts optional */ }
  try { actWin = runWindowScript(await activityRes.text()); } catch { /* activity optional */ }
  return {
    graph,
    texts: (textsWin.BW_TEXTS as Record<string, string>) || {},
    lastOk: (actWin.DTP_LAST_OK as Record<string, string>) || {},
    lastData: (actWin.DTP_LAST_DATA as Record<string, string>) || {},
  };
}
